import { ModalOverlay } from './ModalOverlay';
import React, { useEffect, useRef, useState } from 'react';
import { useApp } from '../context/AppContext';
import { ServiceOrder, Invoice, Payment, TariffRule } from '../types';
import {
  Receipt,
  Plus,
  CreditCard,
  CheckCircle2,
  AlertCircle,
  FileText,
  DollarSign,
  Calendar,
  Layers,
  Search,
} from 'lucide-react';
import { NavTabId } from './Sidebar';

interface BillingViewProps {
  onNavigate: (tab: NavTabId, contextId?: string) => void;
  targetVisitId?: string;
}

export const BillingView: React.FC<BillingViewProps> = ({ onNavigate, targetVisitId }) => {
  const {
    containerVisits,
    serviceOrders,
    invoices,
    payments,
    tariffRules,
    createServiceOrder,
    recordPayment,
    tariffs,
    createTariff,
    addTariffRule,
    activateTariff,
    retireTariff,
    confirmServiceOrder,
    cancelServiceOrder,
    issueInvoice,
  } = useApp();

  const [activeTab, setActiveTab] = useState<'INVOICES' | 'ORDERS' | 'TARIFFS'>('INVOICES');
  const [showCreateSoModal, setShowCreateSoModal] = useState(false);
  const [showPayModal, setShowPayModal] = useState(false);
  const [selectedInvoice, setSelectedInvoice] = useState<Invoice | null>(null);

  // New SO Form state
  const [selectedVisitId, setSelectedVisitId] = useState<string>(
    targetVisitId || containerVisits[0]?.id || ''
  );
  const { previewServiceOrder } = useApp();
  const [preview, setPreview] = useState<{items:any[];totalAmountVnd:number}|null>(null);
  const [previewError, setPreviewError] = useState('');
  useEffect(() => {
    let current = true; setPreview(null); setPreviewError('');
    if (!showCreateSoModal || !selectedVisitId) return;
    previewServiceOrder(selectedVisitId).then(value => {if(current) setPreview(value);}).catch(error => {if(current) setPreviewError(error instanceof Error ? error.message : 'Không tính được phí.');});
    return () => {current = false;};
  },[showCreateSoModal,selectedVisitId,previewServiceOrder]);

  // Payment Form state
  const [payAmount, setPayAmount] = useState<number>(0);
  const [payMethod, setPayMethod] = useState<'CHUYEN_KHOAN' | 'TIEN_MAT'>('CHUYEN_KHOAN');
  const paymentPending = useRef(false);
  const [isPaying, setIsPaying] = useState(false);
  const [paymentError, setPaymentError] = useState('');

  // Tariff management form state
  const [showTariffModal, setShowTariffModal] = useState(false);
  const [tariffName, setTariffName] = useState('Biểu giá mới');
  const [tariffFrom, setTariffFrom] = useState(new Date().toISOString().slice(0, 10));
  const [tariffTo, setTariffTo] = useState('');
  const [showRuleModal, setShowRuleModal] = useState<{ tariffId: string } | null>(null);
  const [ruleForm, setRuleForm] = useState({ serviceType: 'STORAGE', serviceName: 'Phí lưu bãi', containerType: 'ALL', unit: 'ngày', unitPriceVnd: 200000, freeDays: 5 });

  const totalInvoiced = invoices.reduce((acc, i) => acc + i.totalAmountVnd, 0);
  const totalPaid = invoices.reduce((acc, i) => acc + i.paidAmountVnd, 0);
  const totalDebt = totalInvoiced - totalPaid;

  const handleCreateSo = async (e: React.FormEvent) => {
    e.preventDefault();
    const visit = containerVisits.find((c) => c.id === selectedVisitId);
    if (!visit) return;

    if (!preview || previewError) return;
    const result = await createServiceOrder(visit.id);
    alert(result.message);
    if (result.success) setShowCreateSoModal(false);
  };

  const handleRecordPayment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedInvoice || paymentPending.current) return;
    paymentPending.current = true;
    setIsPaying(true);
    setPaymentError('');
    try {
      const result = await recordPayment(selectedInvoice.id, payAmount, payMethod);
      if (!result.success) {
        setPaymentError(result.message);
        return;
      }
      alert(result.message);
      setShowPayModal(false);
      setSelectedInvoice(null);
    } catch (error) {
      setPaymentError(error instanceof Error ? error.message : 'Kh\u00f4ng th\u1ec3 ghi nh\u1eadn thanh to\u00e1n. Vui l\u00f2ng th\u1eed l\u1ea1i.');
    } finally {
      paymentPending.current = false;
      setIsPaying(false);
    }
  };

  const closePaymentModal = () => {
    if (!paymentPending.current) setShowPayModal(false);
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center space-x-2">
            <Receipt className="w-5 h-5 text-blue-600" />
            <span>Dịch vụ & Thanh toán (Billing & Invoices)</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Tính toán biểu phí lưu bãi, tiếp nhận, rút ruột (Stripping), kiểm định và xuất hóa đơn đối soát
          </p>
        </div>

        <button
          onClick={() => setShowCreateSoModal(true)}
          className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-lg transition shadow-xs flex items-center space-x-1.5"
        >
          <Plus className="w-4 h-4" />
          <span>Tạo Đơn dịch vụ (Service Order)</span>
        </button>
      </div>

      {/* Financial Overview Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 text-xs">
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs">
          <span className="text-slate-500 font-semibold uppercase tracking-wider">Tổng phí đã xuất Hóa đơn</span>
          <div className="text-xl font-bold text-slate-900 mt-1">{totalInvoiced.toLocaleString()}₫</div>
          <div className="text-slate-400 mt-1">{invoices.length} hóa đơn phát hành</div>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs">
          <span className="text-slate-500 font-semibold uppercase tracking-wider">Đã thu thực tế</span>
          <div className="text-xl font-bold text-emerald-600 mt-1">{totalPaid.toLocaleString()}₫</div>
          <div className="text-slate-400 mt-1">{payments.length} lượt giao dịch đã ghi nhận</div>
        </div>
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs">
          <span className="text-slate-500 font-semibold uppercase tracking-wider">Công nợ chưa thu</span>
          <div className="text-xl font-bold text-rose-600 mt-1">{totalDebt.toLocaleString()}₫</div>
          <div className="text-slate-400 mt-1">Ảnh hưởng trực tiếp đến điều kiện cấp Gate Pass</div>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex flex-wrap items-center gap-2 border-b border-slate-200 text-xs font-bold [&>button]:whitespace-nowrap">
        <button
          onClick={() => setActiveTab('INVOICES')}
          className={`pb-2.5 px-3 border-b-2 transition ${
            activeTab === 'INVOICES' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'
          }`}
        >
          Hóa đơn phát hành ({invoices.length})
        </button>
        <button
          onClick={() => setActiveTab('ORDERS')}
          className={`pb-2.5 px-3 border-b-2 transition ${
            activeTab === 'ORDERS' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'
          }`}
        >
          Đơn dịch vụ (Service Orders) ({serviceOrders.length})
        </button>
        <button
          onClick={() => setActiveTab('TARIFFS')}
          className={`pb-2.5 px-3 border-b-2 transition ${
            activeTab === 'TARIFFS' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'
          }`}
        >
          Biểu phí dịch vụ (Tariffs) ({tariffRules.length})
        </button>
      </div>

      {/* TAB 1: INVOICES */}
      {activeTab === 'INVOICES' && (
        <div className="bg-white rounded-xl border border-slate-200 shadow-xs overflow-hidden">
          <table className="w-full text-left text-xs">
            <thead className="bg-slate-50 border-b border-slate-200 text-slate-600 font-semibold">
              <tr>
                <th className="py-3 px-4">Số Hóa đơn</th>
                <th className="py-3 px-4">Container</th>
                <th className="py-3 px-4">Chủ hàng (Consignee)</th>
                <th className="py-3 px-4">Ngày xuất</th>
                <th className="py-3 px-4">Hạn TT</th>
                <th className="py-3 px-4">Tổng tiền</th>
                <th className="py-3 px-4">Đã thanh toán</th>
                <th className="py-3 px-4">Trạng thái</th>
                <th className="py-3 px-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {invoices.map((inv) => {
                const remaining = inv.totalAmountVnd - inv.paidAmountVnd;
                return (
                  <tr key={inv.id} className="hover:bg-slate-50">
                    <td className="py-3 px-4 font-mono font-bold text-blue-700">{inv.invoiceNo}</td>
                    <td className="py-3 px-4 font-mono font-semibold text-slate-800">{inv.containerNumber}</td>
                    <td className="py-3 px-4 text-slate-800">{inv.consigneeName}</td>
                    <td className="py-3 px-4 text-slate-500">{new Date(inv.issuedAt).toLocaleDateString('vi-VN')}</td>
                    <td className="py-3 px-4 text-slate-500">{new Date(inv.dueAt).toLocaleDateString('vi-VN')}</td>
                    <td className="py-3 px-4 font-bold text-slate-900">{inv.totalAmountVnd.toLocaleString()}₫</td>
                    <td className="py-3 px-4 font-bold text-emerald-700">{inv.paidAmountVnd.toLocaleString()}₫</td>
                    <td className="py-3 px-4">
                      <span
                        className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                          inv.status === 'PAID'
                            ? 'bg-emerald-100 text-emerald-800'
                            : inv.status === 'PARTIALLY_PAID'
                            ? 'bg-yellow-100 text-yellow-800'
                            : 'bg-rose-100 text-rose-800'
                        }`}
                      >
                        {inv.status}
                      </span>
                    </td>
                    <td className="py-3 px-4 text-right">
                      {remaining > 0 ? (
                        <button
                          disabled={isPaying}
                          onClick={() => {
                            if (paymentPending.current) return;
                            setSelectedInvoice(inv);
                            setPayAmount(remaining);
                            setPaymentError('');
                            setShowPayModal(true);
                          }}
                          className="px-3 py-1 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded shadow-xs"
                        >
                          Ghi nhận Thanh toán
                        </button>
                      ) : (
                        <span className="text-emerald-600 font-semibold flex items-center justify-end">
                          <CheckCircle2 className="w-3.5 h-3.5 mr-1" /> Đã trả đủ
                        </span>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* TAB 2: SERVICE ORDERS */}
      {activeTab === 'ORDERS' && (
        <div className="space-y-4">
          {serviceOrders.map((so) => (
            <div key={so.id} className="bg-white rounded-xl border border-slate-200 p-5 shadow-xs text-xs space-y-3">
              <div className="flex items-center justify-between border-b border-slate-100 pb-2">
                <div className="flex items-center space-x-3">
                  <span className="font-mono font-bold text-sm text-slate-900">{so.orderCode}</span>
                  <span className="px-2 py-0.5 bg-blue-50 text-blue-800 font-mono font-semibold rounded">
                    {so.containerNumber}
                  </span>
                  <span className="text-slate-600">{so.consigneeName}</span>
                  <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                    so.status === 'INVOICED' || so.status === 'PAID' ? 'bg-emerald-100 text-emerald-800' :
                    so.status === 'CONFIRMED' ? 'bg-blue-100 text-blue-800' :
                    so.status === 'CANCELLED' ? 'bg-rose-100 text-rose-800' : 'bg-amber-100 text-amber-800'
                  }`}>
                    {so.status}
                  </span>
                </div>
                <div className="flex items-center gap-3">
                  <div className="font-bold text-sm text-slate-900">
                    Tổng: <span className="text-blue-600">{so.totalAmountVnd.toLocaleString()}₫</span>
                  </div>
                  {so.status === 'DRAFT' && (
                    <div className="flex items-center gap-1.5">
                      <button onClick={async () => alert((await confirmServiceOrder(so.id)).message)} className="px-2.5 py-1 bg-blue-600 hover:bg-blue-700 text-white rounded-md font-bold">Xác nhận</button>
                      <button
                        onClick={async () => {
                          const reason = window.prompt('Lý do hủy Service Order:');
                          if (reason) alert((await cancelServiceOrder(so.id, reason)).message);
                        }}
                        className="px-2.5 py-1 bg-rose-50 hover:bg-rose-100 text-rose-700 rounded-md font-bold border border-rose-200"
                      >
                        Hủy
                      </button>
                    </div>
                  )}
                  {so.status === 'CONFIRMED' && (
                    <button
                      onClick={async () => {
                        const days = window.prompt('Hạn thanh toán (số ngày kể từ hôm nay):', '7');
                        if (days) {
                          const due = new Date(Date.now() + Number(days) * 24 * 60 * 60 * 1000).toISOString();
                          const res = await issueInvoice(so.id, due);
                          alert(res.message);
                        }
                      }}
                      className="px-2.5 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded-md font-bold"
                    >
                      Phát hành Hóa đơn
                    </button>
                  )}
                </div>
              </div>

              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="text-slate-400 font-medium">
                      <th className="pb-1">Tên dịch vụ</th>
                      <th className="pb-1">Số lượng</th>
                      <th className="pb-1">Đơn vị</th>
                      <th className="pb-1">Đơn giá</th>
                      <th className="pb-1 text-right">Thành tiền</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {so.items.map((item) => (
                      <tr key={item.id} className="text-slate-700">
                        <td className="py-1.5 font-medium">{item.serviceName}</td>
                        <td className="py-1.5">{item.quantity}</td>
                        <td className="py-1.5">{item.unit}</td>
                        <td className="py-1.5">{item.unitPriceVnd.toLocaleString()}₫</td>
                        <td className="py-1.5 font-bold text-right">{item.amountVnd.toLocaleString()}₫</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* TAB 3: TARIFFS */}
      {activeTab === 'TARIFFS' && (
        <div className="space-y-4">
          <div className="flex justify-end">
            <button
              onClick={() => setShowTariffModal(true)}
              className="px-3.5 py-2 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold rounded-lg flex items-center gap-1.5"
            >
              <Plus className="w-4 h-4" /> Tạo Bảng giá (Tariff)
            </button>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {tariffs.map((t) => (
              <div key={t.id} className="bg-white rounded-xl border border-slate-200 p-4 text-xs">
                <div className="flex items-center justify-between mb-2">
                  <div>
                    <div className="font-bold text-slate-800">{t.name}</div>
                    <div className="text-slate-500">Hiệu lực: {t.effectiveFrom} {t.effectiveTo ? `→ ${t.effectiveTo}` : ''}</div>
                  </div>
                  <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                    t.status === 'ACTIVE' ? 'bg-emerald-100 text-emerald-800' : t.status === 'RETIRED' ? 'bg-slate-200 text-slate-600' : 'bg-amber-100 text-amber-800'
                  }`}>
                    {t.status}
                  </span>
                </div>
                <div className="flex items-center gap-1.5 mt-2">
                  <button onClick={() => setShowRuleModal({ tariffId: t.id })} className="px-2.5 py-1 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-md font-bold">
                    + Quy tắc giá
                  </button>
                  {t.status === 'DRAFT' && (
                    <button onClick={async () => alert((await activateTariff(t.id)).message)} className="px-2.5 py-1 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 rounded-md font-bold border border-emerald-200">
                      Kích hoạt
                    </button>
                  )}
                  {t.status === 'ACTIVE' && (
                    <button onClick={async () => alert((await retireTariff(t.id)).message)} className="px-2.5 py-1 bg-rose-50 hover:bg-rose-100 text-rose-700 rounded-md font-bold border border-rose-200">
                      Ngừng sử dụng
                    </button>
                  )}
                  <span className="text-slate-400 ml-auto">{t.ruleIds.length} quy tắc</span>
                </div>
              </div>
            ))}
          </div>

          <div className="bg-white rounded-xl border border-slate-200 shadow-xs overflow-hidden">
          <table className="w-full text-left text-xs">
            <thead className="bg-slate-50 border-b border-slate-200 text-slate-600 font-semibold">
              <tr>
                <th className="py-3 px-4">Mã dịch vụ</th>
                <th className="py-3 px-4">Tên dịch vụ</th>
                <th className="py-3 px-4">Áp dụng Container</th>
                <th className="py-3 px-4">Đơn vị tính</th>
                <th className="py-3 px-4">Đơn giá quy định</th>
                <th className="py-3 px-4">Ngày miễn phí (Free days)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {tariffRules.map((tr) => (
                <tr key={tr.id} className="hover:bg-slate-50">
                  <td className="py-3 px-4 font-mono font-bold text-slate-800">{tr.serviceType}</td>
                  <td className="py-3 px-4 font-medium text-slate-900">{tr.serviceName}</td>
                  <td className="py-3 px-4 font-semibold text-blue-700">{tr.containerType || 'ALL'}</td>
                  <td className="py-3 px-4 text-slate-600">{tr.unit}</td>
                  <td className="py-3 px-4 font-bold text-emerald-700">{tr.unitPriceVnd.toLocaleString()}₫</td>
                  <td className="py-3 px-4 text-slate-600">{tr.freeDays ? `${tr.freeDays} ngày` : '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
          </div>
        </div>
      )}

      {/* Create Tariff Modal */}
      {showTariffModal && (
        <ModalOverlay aria-labelledby="billing-dialog-1-title" onClose={() => setShowTariffModal(false)} className="fixed inset-0 bg-slate-900/40 backdrop-blur-xs flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-sm w-full p-6 shadow-xl border border-slate-200 text-xs">
            <h3 id="billing-dialog-1-title" className="text-base font-bold text-slate-900 mb-4">Tạo Bảng giá mới</h3>
            <div className="space-y-3">
              <div>
                <label htmlFor="billing-tariff-name" className="block font-semibold text-slate-700 mb-1">Tên bảng giá*</label>
                <input id="billing-tariff-name" value={tariffName} onChange={(e) => setTariffName(e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-lg" />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label htmlFor="billing-tariff-from" className="block font-semibold text-slate-700 mb-1">Hiệu lực từ*</label>
                  <input id="billing-tariff-from" type="date" value={tariffFrom} onChange={(e) => setTariffFrom(e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-lg" />
                </div>
                <div>
                  <label htmlFor="billing-tariff-to" className="block font-semibold text-slate-700 mb-1">Hiệu lực đến</label>
                  <input id="billing-tariff-to" type="date" value={tariffTo} onChange={(e) => setTariffTo(e.target.value)} className="w-full px-3 py-2 border border-slate-300 rounded-lg" />
                </div>
              </div>
            </div>
            <div className="flex justify-end space-x-2 pt-4 mt-2 border-t border-slate-200">
              <button onClick={() => setShowTariffModal(false)} className="px-4 py-2 border border-slate-300 text-slate-700 rounded-lg font-medium">Hủy</button>
              <button
                onClick={async () => {
                  const result = await createTariff(tariffName, tariffFrom, tariffTo || undefined);
                  alert(result.message);
                  if (result.success) setShowTariffModal(false);
                }}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700"
              >
                Tạo
              </button>
            </div>
          </div>
        </ModalOverlay>
      )}

      {/* Add Tariff Rule Modal */}
      {showRuleModal && (
        <ModalOverlay aria-labelledby="billing-dialog-2-title" onClose={() => setShowRuleModal(null)} className="fixed inset-0 bg-slate-900/40 backdrop-blur-xs flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-sm w-full p-6 shadow-xl border border-slate-200 text-xs">
            <h3 id="billing-dialog-2-title" className="text-base font-bold text-slate-900 mb-4">Thêm Quy tắc giá</h3>
            <div className="space-y-3">
              <div>
                <label htmlFor="billing-rule-form-service-type" className="block font-semibold text-slate-700 mb-1">Mã loại dịch vụ*</label>
                <select id="billing-rule-form-service-type" value={ruleForm.serviceType} onChange={(e) => setRuleForm({ ...ruleForm, serviceType: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white">
                  <option value="RECEPTION">RECEPTION — Tiếp nhận</option>
                  <option value="STORAGE">STORAGE — Lưu bãi</option>
                  <option value="MOVEMENT">MOVEMENT — Di chuyển nội bãi</option>
                  <option value="STRIPPING">STRIPPING — Rút hàng</option>
                  <option value="INSPECTION">INSPECTION — Kiểm định</option>
                </select>
              </div>
              <p className="text-slate-500">Tên dịch vụ và đơn vị tính lấy từ danh mục. Quy tắc này áp dụng mọi kích thước và loại container.</p>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label htmlFor="billing-rule-form-unit-price-vnd" className="block font-semibold text-slate-700 mb-1">Đơn giá (VNĐ)</label>
                  <input id="billing-rule-form-unit-price-vnd" type="number" value={ruleForm.unitPriceVnd} onChange={(e) => setRuleForm({ ...ruleForm, unitPriceVnd: Number(e.target.value) })} className="w-full px-3 py-2 border border-slate-300 rounded-lg" />
                </div>
              </div>
            </div>
            <div className="flex justify-end space-x-2 pt-4 mt-2 border-t border-slate-200">
              <button onClick={() => setShowRuleModal(null)} className="px-4 py-2 border border-slate-300 text-slate-700 rounded-lg font-medium">Hủy</button>
              <button
                onClick={async () => {
                  const result = await addTariffRule(showRuleModal.tariffId, { ...ruleForm, serviceType: ruleForm.serviceType as any, unit: ruleForm.unit as any, containerType: ruleForm.containerType as any });
                  alert(result.message);
                  if (result.success) setShowRuleModal(null);
                }}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700"
              >
                Lưu
              </button>
            </div>
          </div>
        </ModalOverlay>
      )}

      {/* Create SO Modal */}
      {showCreateSoModal && (
        <ModalOverlay aria-labelledby="billing-dialog-3-title" onClose={() => setShowCreateSoModal(false)} className="fixed inset-0 bg-slate-900/40 backdrop-blur-xs flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-6 shadow-xl border border-slate-200 text-xs">
            <h3 id="billing-dialog-3-title" className="text-base font-bold text-slate-900 mb-4">Tạo Đơn dịch vụ (Service Order) mới</h3>
            <form onSubmit={handleCreateSo} className="space-y-4">
              <div>
                <label htmlFor="billing-selected-visit-id" className="block font-semibold text-slate-700 mb-1">Chọn Container*</label>
                <select id="billing-selected-visit-id"
                  value={selectedVisitId}
                  onChange={(e) => setSelectedVisitId(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg font-mono font-bold bg-white"
                >
                  {containerVisits.map((c) => (
                    <option key={c.id} value={c.id}>
                      {c.containerNumber} — {c.consigneeName} ({c.containerType})
                    </option>
                  ))}
                </select>
              </div>

              <p className="text-slate-500">Phí được backend tính theo tác nghiệp thực tế và biểu giá đang hiệu lực.</p>
              {previewError ? <p role="alert" className="text-rose-700">{previewError}</p> : preview ? <div className="space-y-2 rounded-lg bg-slate-50 p-3">{preview.items.map((item,index) => <div key={index} className="flex flex-wrap justify-between gap-2"><span>{item.serviceName} · {item.quantity} {item.unit}</span><strong>{item.amountVnd.toLocaleString()} ₫</strong></div>)}<div className="border-t pt-2 font-bold">Tổng dự kiến: {preview.totalAmountVnd.toLocaleString()} ₫</div></div> : <p role="status">Đang tính phí từ backend…</p>}

              <div className="flex justify-end space-x-2 pt-3 border-t border-slate-200">
                <button
                  type="button"
                  onClick={() => setShowCreateSoModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-slate-700"
                >
                  Hủy
                </button>
                <button
                  type="submit"
                  disabled={!preview || !!previewError || preview.items.length === 0}
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700"
                >
                  Tạo đơn dịch vụ nháp
                </button>
              </div>
            </form>
          </div>
        </ModalOverlay>
      )}

      {/* Record Payment Modal */}
      {showPayModal && selectedInvoice && (
        <ModalOverlay aria-labelledby="billing-dialog-4-title" onClose={closePaymentModal} pending={isPaying} className="fixed inset-0 bg-slate-900/40 backdrop-blur-xs flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-6 shadow-xl border border-slate-200 text-xs">
            <h3 id="billing-dialog-4-title" className="text-base font-bold text-slate-900 mb-2">Ghi nhận Thanh toán Hóa đơn</h3>
            <p className="text-slate-500 mb-4">
              Hóa đơn <strong>{selectedInvoice.invoiceNo}</strong> ({selectedInvoice.containerNumber}) — Chủ hàng:{' '}
              {selectedInvoice.consigneeName}
            </p>

            <form onSubmit={handleRecordPayment} aria-busy={isPaying} className="space-y-4">
              <div>
                <label htmlFor="billing-pay-amount" className="block font-semibold text-slate-700 mb-1">Số tiền thanh toán (VNĐ)*</label>
                <input id="billing-pay-amount"
                  type="number"
                  required
                  value={payAmount}
                  disabled={isPaying}
                  onChange={(e) => {
                    if (!paymentPending.current) setPayAmount(parseInt(e.target.value, 10) || 0);
                  }}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-base font-bold text-emerald-700"
                />
              </div>

              <div>
                <label htmlFor="billing-pay-method" className="block font-semibold text-slate-700 mb-1">Phương thức thanh toán*</label>
                <select id="billing-pay-method"
                  value={payMethod}
                  disabled={isPaying}
                  onChange={(e) => {
                    if (!paymentPending.current) setPayMethod(e.target.value as 'CHUYEN_KHOAN' | 'TIEN_MAT');
                  }}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white font-semibold"
                >
                  <option value="CHUYEN_KHOAN">Chuyển khoản Ngân hàng (Bank Transfer)</option>
                  <option value="TIEN_MAT">Tiền mặt tại Quầy Thủ quỹ</option>
                </select>
              </div>

              {paymentError && <p role="alert" className="text-rose-700">{paymentError}</p>}

              <div className="flex justify-end space-x-2 pt-3 border-t border-slate-200">
                <button
                  type="button"
                  disabled={isPaying}
                  onClick={closePaymentModal}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-slate-700 disabled:opacity-50"
                >
                  Hủy
                </button>
                <button
                  type="submit"
                  disabled={isPaying}
                  className="px-4 py-2 bg-emerald-600 text-white rounded-lg font-bold hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-wait"
                >
                  {isPaying ? '\u0110ang ghi nh\u1eadn...' : 'X\u00e1c nh\u1eadn Thu ti\u1ec1n'}
                </button>
              </div>
            </form>
          </div>
        </ModalOverlay>
      )}
    </div>
  );
};

import { ModalOverlay } from './ModalOverlay';
import React, { useEffect, useState } from 'react';
import { useApp } from '../context/AppContext';
import { readinessLabel } from '../services/readiness-labels';
import { ContainerVisit, ContainerState, HoldType } from '../types';
import {
  Boxes,
  Search,
  Filter,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  Clock,
  Warehouse,
  Receipt,
  QrCode,
  History,
  ShieldAlert,
  Send,
  Plus,
  ExternalLink,
  ChevronRight,
  ShieldCheck,
  FileText,
} from 'lucide-react';
import { NavTabId } from './Sidebar';
import { useBackendReadiness } from './useBackendReadiness';
import { CriticalDataNotice } from './CriticalDataNotice';

import { useCommandAction, CommandNotice } from './useCommandAction';
import { useFormValidation, FormErrors } from './useFormValidation';
import { CollectionState } from './CollectionState';
import QRCode from 'react-qr-code';
import { effectiveGatePassStatus } from '../lib/gate-pass';
import { ReadinessNotice } from './ReadinessNotice';

interface ContainersViewProps {
  onNavigate: (tab: NavTabId, contextId?: string) => void;
  selectedVisitId?: string;
}

export const ContainersView: React.FC<ContainersViewProps> = ({ onNavigate, selectedVisitId }) => {
  const {
    containerVisits,
    manifests,
    consignees,
    holds,
    visitSafetyStatus = {},
    invoices,
    serviceOrders,
    gatePasses,
    handovers,
    yardSlots,
    createOperationalHold,
    releaseOperationalHold,
    createGatePass,
    createContainerVisit,
    cancelContainerVisit,
    createMovementOrder,
    movementOrders,
  } = useApp();

  const action = useCommandAction();
  const [showCreateVisit, setShowCreateVisit] = useState(false);
  const [cvForm, setCvForm] = useState({
    containerNumber: '',
    containerType: '40HC' as ContainerVisit['containerType'],
    consigneeName: '',
    shippingLine: '',
    manifestNo: '',
    mblNumber: '',
    hblNumber: '',
    manifestSeal: '',
    grossWeightKg: 0,
  });

  const [searchTerm, setSearchTerm] = useState('');
  const formManifest = manifests.find(m => m.manifestNo === cvForm.manifestNo);
  const formMaster = formManifest?.masterBills.find(m => m.mblNumber === cvForm.mblNumber);
  const [stateFilter, setStateFilter] = useState<string>('ALL');
  const [hasBlockerOnly, setHasBlockerOnly] = useState(false);

  // Selected container modal
  const [activeModalVisitId, setActiveModalVisitId] = useState<string | null>(selectedVisitId || null);
  const [activeDetailTab, setActiveDetailTab] = useState<'OVERVIEW' | 'YARD_OPS' | 'BILLING' | 'GATE_PASS' | 'TIMELINE' | 'HOLDS'>('OVERVIEW');

  // New Hold Form
  const [showAddHold, setShowAddHold] = useState(false);
  const [newHoldType, setNewHoldType] = useState<HoldType>('CUSTOMS');
  const [newHoldReason, setNewHoldReason] = useState('');

  // Gate Pass Form in modal
  const [gpPlate, setGpPlate] = useState('');
  const [gpReceiver, setGpReceiver] = useState('');
  const [gpCccd, setGpCccd] = useState('');

  useEffect(() => {
    if (selectedVisitId) {
      setActiveModalVisitId(selectedVisitId);
      setActiveDetailTab('OVERVIEW');
    }
  }, [selectedVisitId]);

  const filteredVisits = containerVisits.filter((v) => {
    if (searchTerm) {
      const q = searchTerm.toLowerCase();
      const matchNo = v.containerNumber.toLowerCase().includes(q);
      const matchCsg = v.consigneeName.toLowerCase().includes(q);
      const matchMnf = v.manifestNo.toLowerCase().includes(q);
      if (!matchNo && !matchCsg && !matchMnf) return false;
    }

    if (stateFilter !== 'ALL' && v.state !== stateFilter) return false;

    if (hasBlockerOnly) {
      const activeHolds = holds.filter((h) => h.containerVisitId === v.id && h.status === 'ACTIVE');
      const invs = invoices.filter((i) => i.containerVisitId === v.id && i.status !== 'PAID');
      if (visitSafetyStatus[v.id]?.holds === 'ready' && activeHolds.length === 0 && invs.length === 0 && v.currentLocation) return false;
    }

    return true;
  });

  const activeVisit = containerVisits.find((v) => v.id === activeModalVisitId);
  const activeVisitHolds = activeVisit ? holds.filter((h) => h.containerVisitId === activeVisit.id) : [];
  const activeVisitInvoices = activeVisit ? invoices.filter((i) => i.containerVisitId === activeVisit.id) : [];
  const activeVisitOrders = activeVisit ? serviceOrders.filter((s) => s.containerVisitId === activeVisit.id) : [];
  const activeVisitGatePass = activeVisit ? gatePasses.find((gp) => gp.containerVisitId === activeVisit.id && effectiveGatePassStatus(gp) === 'ACTIVE') : null;
  const activeVisitHandover = activeVisit ? handovers.find((h) => h.containerVisitId === activeVisit.id) : null;
  const holdsReady = activeVisit && visitSafetyStatus[activeVisit.id]?.holds === 'ready';
  const passesReady = activeVisit && visitSafetyStatus[activeVisit.id]?.gatePasses === 'ready';

  const evaluation = useBackendReadiness(activeVisit?.id);
  const { readiness, readinessError, isCheckingReadiness } = evaluation;

  const getStateBadge = (state: ContainerState) => {
    switch (state) {
      case 'PENDING':
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-700">PENDING</span>;
      case 'AUTHORIZED':
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-blue-100 text-blue-800">AUTHORIZED</span>;
      case 'IN_YARD':
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-100 text-emerald-800">IN_YARD</span>;
      case 'UNDER_INSPECTION':
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-100 text-amber-800">UNDER_INSPECTION</span>;
      case 'IN_STRIPPING':
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-purple-100 text-purple-800">IN_STRIPPING</span>;
      case 'GATE_PASS_ISSUED':
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-indigo-100 text-indigo-800">GATE_PASS_ISSUED</span>;
      case 'EXITED':
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-200 text-slate-800">EXITED</span>;
      default:
        return <span className="px-2 py-0.5 rounded-full text-[10px] font-bold bg-slate-100 text-slate-600">{state}</span>;
    }
  };

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center space-x-2">
            <Boxes className="w-5 h-5 text-blue-600" />
            <span>Container 360 · Danh sách & vòng đời</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Theo dõi trạng thái vòng đời, vị trí bãi Yard, thời gian lưu bãi (Dwell days), Holds và kiểm tra điều kiện ra cổng (Readiness)
          </p>
        </div>

        <div className="flex items-center space-x-2 text-xs">
          <span className="px-3 py-1 bg-slate-100 rounded-lg text-slate-700 font-semibold">
            Tổng cộng: {containerVisits.length} containers
          </span>
          <button
            onClick={() => setShowCreateVisit(true)}
            className="px-3.5 py-2 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold rounded-lg transition shadow-xs flex items-center space-x-1.5"
          >
            <Plus className="w-4 h-4" />
            <span>Tạo Container Visit</span>
          </button>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs flex flex-wrap items-center justify-between gap-3 text-xs">
        <div className="flex flex-wrap items-center gap-2.5">
          <div className="relative w-64">
            <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
            <input
              type="text"
              placeholder="Tìm theo số cont, chủ hàng, manifest..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-3 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-1 focus:ring-blue-500 bg-slate-50"
            />
          </div>

          <select
            value={stateFilter}
            onChange={(e) => setStateFilter(e.target.value)}
            className="border border-slate-200 rounded-lg px-2.5 py-2 bg-slate-50 text-slate-700 font-medium"
          >
            <option value="ALL">Tất cả trạng thái</option>
            <option value="PENDING">Pending</option>
            <option value="AUTHORIZED">Authorized (Chờ cổng)</option>
            <option value="IN_YARD">In Yard (Trong bãi)</option>
            <option value="UNDER_INSPECTION">Under Inspection</option>
            <option value="GATE_PASS_ISSUED">Gate Pass Issued</option>
            <option value="EXITED">Exited (Đã ra cổng)</option>
          </select>

          <label className="flex items-center space-x-1.5 cursor-pointer ml-2 text-slate-700 select-none">
            <input
              type="checkbox"
              checked={hasBlockerOnly}
              onChange={(e) => setHasBlockerOnly(e.target.checked)}
              className="rounded border-slate-300 text-blue-600 focus:ring-blue-500"
            />
            <span>Chỉ container có Blocker (Lệnh giữ / Chưa thanh toán / Chưa vị trí)</span>
          </label>
        </div>

        <span className="text-slate-400">Hiển thị {filteredVisits.length} containers</span>
      </div>

      {/* Container Table */}
      <div className="bg-white rounded-xl border border-slate-200 shadow-xs overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead className="bg-slate-50 border-b border-slate-200 text-slate-600 font-semibold">
              <tr>
                <th className="py-3 px-4">Số Container</th>
                <th className="py-3 px-4">Loại</th>
                <th className="py-3 px-4">Chủ hàng (Consignee)</th>
                <th className="py-3 px-4">Vị trí Bãi</th>
                <th className="py-3 px-4">Trạng thái</th>
                <th className="py-3 px-4">Vào cổng</th>
                <th className="py-3 px-4">Ngày lưu</th>
                <th className="py-3 px-4">Blockers</th>
                <th className="py-3 px-4 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredVisits.map((v) => {
                const activeHoldsCount = holds.filter((h) => h.containerVisitId === v.id && h.status === 'ACTIVE').length;
                const hasUnpaid = invoices.some((i) => i.containerVisitId === v.id && i.status !== 'PAID');
                const dwellDays = v.gateInAt
                  ? Math.floor((Date.now() - new Date(v.gateInAt).getTime()) / (24 * 3600 * 1000))
                  : 0;
                const isOverFree = v.freeDays !== undefined && dwellDays > v.freeDays;

                return (
                  <tr key={v.id} className="hover:bg-slate-50/80 transition">
                    <td className="py-3 px-4 font-mono font-bold text-blue-700">{v.containerNumber}</td>
                    <td className="py-3 px-4 font-semibold text-slate-700">{v.containerType}</td>
                    <td className="py-3 px-4 text-slate-800 max-w-[200px] truncate">{v.consigneeName}</td>
                    <td className="py-3 px-4 font-mono font-semibold text-slate-900">
                      {v.currentLocation ? (
                        <span className="px-2 py-0.5 bg-blue-50 text-blue-800 rounded border border-blue-200">
                          {v.currentLocation}
                        </span>
                      ) : (
                        <span className="text-slate-400 italic">Chưa xếp</span>
                      )}
                    </td>
                    <td className="py-3 px-4">{getStateBadge(v.state)}</td>
                    <td className="py-3 px-4 text-slate-500">
                      {v.gateInAt ? new Date(v.gateInAt).toLocaleDateString('vi-VN') : '—'}
                    </td>
                    <td className="py-3 px-4">
                      {v.gateInAt ? (
                        <span className={`font-semibold ${isOverFree ? 'text-rose-600' : 'text-slate-700'}`}>
                          {dwellDays} ngày {isOverFree && <span className="text-[10px] text-rose-500">(quá hạn)</span>}
                        </span>
                      ) : (
                        '—'
                      )}
                    </td>
                    <td className="py-3 px-4">
                      <div className="flex items-center space-x-1.5">
                        {visitSafetyStatus[v.id]?.holds !== 'ready' && <span className="text-amber-900" title="Chưa xác minh lệnh giữ">Holds chưa kiểm tra</span>}
                        {visitSafetyStatus[v.id]?.holds === 'ready' && activeHoldsCount > 0 && (
                          <span
                            title="Có lệnh giữ (Hold)"
                            className="p-1 bg-amber-100 text-amber-800 rounded-md inline-flex items-center"
                          >
                            <ShieldAlert className="w-3.5 h-3.5" />
                          </span>
                        )}
                        {hasUnpaid && (
                          <span
                            title="Còn công nợ chưa thanh toán"
                            className="p-1 bg-rose-100 text-rose-800 rounded-md inline-flex items-center"
                          >
                            <Receipt className="w-3.5 h-3.5" />
                          </span>
                        )}
                        {!v.currentLocation && v.state === 'IN_YARD' && (
                          <span
                            title="Chưa xếp vị trí bãi"
                            className="p-1 bg-blue-100 text-blue-800 rounded-md inline-flex items-center"
                          >
                            <Warehouse className="w-3.5 h-3.5" />
                          </span>
                        )}
                        {visitSafetyStatus[v.id]?.holds === 'ready' && activeHoldsCount === 0 && !hasUnpaid && v.currentLocation && (
                          <span className="text-emerald-600 inline-flex items-center">
                            <CheckCircle2 className="w-4 h-4" />
                          </span>
                        )}
                      </div>
                    </td>
                    <td className="py-3 px-4 text-right">
                      <button
                        onClick={() => {
                          setActiveModalVisitId(v.id);
                          setActiveDetailTab('OVERVIEW');
                        }}
                        className="px-2.5 py-1 text-xs font-bold text-blue-600 hover:bg-blue-50 rounded transition"
                      >
                        Chi tiết →
                      </button>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Comprehensive Container Detail Modal (6 Tabs) */}
      {activeVisit && (
        <ModalOverlay aria-label={`Container 360 ${activeVisit.containerNumber}`} onClose={() => setActiveModalVisitId(null)} className="fixed inset-0 bg-slate-900/50 backdrop-blur-xs flex items-center justify-center z-50 p-4 overflow-y-auto">
          <div className="bg-white rounded-2xl max-w-5xl w-full p-6 shadow-2xl border border-slate-200 max-h-[90vh] flex flex-col my-auto">
            {/* Modal Header */}
            <div className="flex items-start justify-between pb-4 border-b border-slate-200">
              <div>
                <div className="flex items-center space-x-3">
                  <h3 className="text-xl font-bold font-mono text-slate-900">{activeVisit.containerNumber}</h3>
                  {getStateBadge(activeVisit.state)}
                  <span className="text-xs font-semibold px-2.5 py-0.5 bg-slate-100 text-slate-700 rounded-md">
                    {activeVisit.containerType}
                  </span>
                </div>
                <p className="text-xs text-slate-500 mt-1">
                  Chủ hàng: <strong className="text-slate-800">{activeVisit.consigneeName}</strong> · Hãng tàu: <strong>{activeVisit.shippingLine}</strong> · Manifest: <strong>{activeVisit.manifestNo}</strong>
                </p>
              </div>
              <button
                onClick={() => setActiveModalVisitId(null)}
                aria-label="Đóng chi tiết container"
                className="w-8 h-8 rounded-lg bg-slate-100 hover:bg-slate-200 text-slate-500 flex items-center justify-center"
              >
                ✕
              </button>
            </div>

            {/* Navigation Tabs */}
            <div className="flex items-center space-x-1 border-b border-slate-200 mt-4 overflow-x-auto text-xs shrink-0">
              <button
                onClick={() => setActiveDetailTab('OVERVIEW')}
                className={`px-4 py-2 font-bold border-b-2 transition ${
                  activeDetailTab === 'OVERVIEW' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'
                }`}
              >
                Tổng quan & Readiness
              </button>
              <button
                onClick={() => setActiveDetailTab('YARD_OPS')}
                className={`px-4 py-2 font-bold border-b-2 transition ${
                  activeDetailTab === 'YARD_OPS' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'
                }`}
              >
                Tác nghiệp bãi
              </button>
              <button
                onClick={() => setActiveDetailTab('BILLING')}
                className={`px-4 py-2 font-bold border-b-2 transition ${
                  activeDetailTab === 'BILLING' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'
                }`}
              >
                Dịch vụ & Thanh toán ({activeVisitInvoices.length})
              </button>
              <button
                onClick={() => setActiveDetailTab('GATE_PASS')}
                className={`px-4 py-2 font-bold border-b-2 transition ${
                  activeDetailTab === 'GATE_PASS' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'
                }`}
              >
                Phiếu ra cổng
              </button>
              <button
                onClick={() => setActiveDetailTab('HOLDS')}
                className={`px-4 py-2 font-bold border-b-2 transition ${
                  activeDetailTab === 'HOLDS' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'
                }`}
              >
                Lệnh giữ Holds ({holdsReady ? activeVisitHolds.filter((h) => h.status === 'ACTIVE').length : '?'})
              </button>
              <button
                onClick={() => setActiveDetailTab('TIMELINE')}
                className={`px-4 py-2 font-bold border-b-2 transition ${
                  activeDetailTab === 'TIMELINE' ? 'border-blue-600 text-blue-600' : 'border-transparent text-slate-500 hover:text-slate-800'
                }`}
              >
                Dòng thời gian
              </button>
            </div>

            {/* Modal Body */}
            <div className="flex-1 overflow-y-auto py-5 space-y-5 text-xs">
              {/* TAB 1: OVERVIEW */}
              {activeDetailTab === 'OVERVIEW' && (
                <div className="space-y-5">
                  {/* Readiness Checklist Card */}
                  <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
                    <h4 className="font-bold text-slate-800 mb-2 flex items-center justify-between">
                      <span>Kiểm tra Điều kiện Sẵn sàng Cấp Phiếu Ra Cổng (Readiness Checklist)</span>
                      <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold ${
                        readiness?.blockers.length === 0 ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800'
                      }`}>
                        {isCheckingReadiness ? 'ĐANG KIỂM TRA' : readiness ? (readiness.blockers.length === 0 ? 'ĐẠT' : `${readiness.blockers.length} ĐIỀU KIỆN CHƯA ĐẠT`) : 'CHƯA CÓ KẾT QUẢ'}
                      </span>
                    </h4>

                    {readinessError && <p role="alert" className="mt-3 text-rose-700">{readinessError}</p>}
                    {readiness && <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 mt-3">
                      <div className="flex items-center space-x-2 bg-white p-2.5 rounded-lg border border-slate-200">
                        {readiness?.isContainerInYard ? <CheckCircle2 className="w-4 h-4 text-emerald-600" /> : <XCircle className="w-4 h-4 text-rose-600" />}
                        <span>Trong bãi (IN_YARD)</span>
                      </div>
                      <div className="flex items-center space-x-2 bg-white p-2.5 rounded-lg border border-slate-200">
                        {readiness?.hasYardPosition ? <CheckCircle2 className="w-4 h-4 text-emerald-600" /> : <XCircle className="w-4 h-4 text-rose-600" />}
                        <span>Đã có vị trí bãi</span>
                      </div>
                      <div className="flex items-center space-x-2 bg-white p-2.5 rounded-lg border border-slate-200">
                        {readiness?.isBillingCompleted ? <CheckCircle2 className="w-4 h-4 text-emerald-600" /> : <XCircle className="w-4 h-4 text-rose-600" />}
                        <span>Thanh toán đủ 100%</span>
                      </div>
                      <div className="flex items-center space-x-2 bg-white p-2.5 rounded-lg border border-slate-200">
                        {readiness?.hasNoActiveYardOps ? <CheckCircle2 className="w-4 h-4 text-emerald-600" /> : <XCircle className="w-4 h-4 text-rose-600" />}
                        <span>Không vướng tác nghiệp</span>
                      </div>
                      <div className="flex items-center space-x-2 bg-white p-2.5 rounded-lg border border-slate-200">
                        {readiness?.hasNoInspectionHold ? <CheckCircle2 className="w-4 h-4 text-emerald-600" /> : <XCircle className="w-4 h-4 text-rose-600" />}
                        <span>Không giữ kiểm định</span>
                      </div>
                      <div className="flex items-center space-x-2 bg-white p-2.5 rounded-lg border border-slate-200">
                        {readiness?.hasNoOperationalHold ? <CheckCircle2 className="w-4 h-4 text-emerald-600" /> : <XCircle className="w-4 h-4 text-rose-600" />}
                        <span>Không lệnh giữ (Hold)</span>
                      </div>
                    </div>}

                    {readiness && readiness.blockers.length > 0 && (
                      <div className="mt-3 p-2.5 bg-rose-50 border border-rose-200 rounded-lg text-rose-800">
                        <strong>Các nguyên nhân chưa thể cấp Phiếu ra cổng:</strong>
                        <ul className="list-disc pl-4 mt-1 space-y-0.5">
                          {readiness.blockers.map((b, idx) => (
                            <li key={idx}>{readinessLabel(b)}</li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </div>

                  {/* Movement Order & Visit Actions */}
                  <div className="bg-white p-4 rounded-xl border border-slate-200">
                    <h4 className="font-bold text-slate-800 mb-2 flex items-center justify-between">
                      <span>Movement Order (Lệnh cho phép di chuyển về ICD)</span>
                      {(() => {
                        const mo = movementOrders.find((o) => o.containerVisitId === activeVisit.id && o.status !== 'CANCELLED');
                        return mo ? (
                          <span className={`px-2.5 py-0.5 rounded-full text-[10px] font-bold ${
                            mo.status === 'AUTHORIZED' ? 'bg-emerald-100 text-emerald-800' : mo.status === 'DRAFT' ? 'bg-amber-100 text-amber-800' : 'bg-slate-100 text-slate-600'
                          }`}>
                            {mo.orderCode} · {mo.status}
                          </span>
                        ) : (
                          <span className="text-slate-400 italic text-[11px]">Chưa có Movement Order</span>
                        );
                      })()}
                    </h4>
                    <div className="flex items-center gap-2 mt-2">
                      {!movementOrders.some((o) => o.containerVisitId === activeVisit.id && o.status !== 'CANCELLED') && activeVisit.state === 'PENDING' && (
                        <button
                          onClick={async () => alert((await createMovementOrder(activeVisit.id)).message)}
                          className="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-bold"
                        >
                          + Tạo Movement Order
                        </button>
                      )}
                      {['PENDING', 'AUTHORIZED'].includes(activeVisit.state) && (
                        <button
                          onClick={async () => {
                            const reason = window.prompt('Lý do hủy Container Visit:');
                            if (reason) {
                              const res = await cancelContainerVisit(activeVisit.id, reason);
                              alert(res.message);
                              if (res.success) setActiveModalVisitId(null);
                            }
                          }}
                          className="px-3 py-1.5 bg-rose-50 hover:bg-rose-100 text-rose-700 rounded-lg font-bold border border-rose-200"
                        >
                          Hủy Container Visit
                        </button>
                      )}
                      <button
                        onClick={() => {
                          setActiveModalVisitId(null);
                          onNavigate('movement-orders' as NavTabId, activeVisit.id);
                        }}
                        className="px-3 py-1.5 text-blue-600 font-bold hover:underline"
                      >
                        Xem tất cả Movement Order →
                      </button>
                    </div>
                  </div>

                  {/* Transport Handover (Module 13) Card inside Container Detail */}
                  <div className="bg-indigo-50/70 p-4 rounded-xl border border-indigo-200">
                    <div className="flex items-center justify-between mb-2">
                      <div className="flex items-center space-x-2">
                        <Send className="w-4 h-4 text-indigo-700" />
                        <span className="font-bold text-indigo-950">Bàn giao vận chuyển ngoài ICD</span>
                      </div>
                      {activeVisitHandover ? (
                        <span className="px-2.5 py-0.5 rounded-full text-[10px] font-bold bg-indigo-200 text-indigo-900 border border-indigo-300">
                          {activeVisitHandover.status}
                        </span>
                      ) : (
                        <span className="text-slate-400 italic">Chưa tạo Handover</span>
                      )}
                    </div>

                    {activeVisitHandover ? (
                      <div className="bg-white p-3 rounded-lg border border-indigo-200 space-y-2">
                        <div className="flex items-center justify-between">
                          <div>
                            <span className="text-slate-500">Mã vận chuyển:</span>{' '}
                            <strong className="font-mono text-indigo-700">{activeVisitHandover.transportCode}</strong>
                          </div>
                          <div>
                            <span className="text-slate-500">Đối tác:</span>{' '}
                            <strong className="text-slate-800">{activeVisitHandover.partnerName}</strong>
                          </div>
                        </div>
                        <div className="text-slate-600">
                          Kho nhận đích: <strong>{activeVisitHandover.warehouseName}</strong> ({activeVisitHandover.warehouseAddress})
                        </div>
                        <div className="flex items-center justify-between text-[11px] text-slate-500 pt-1 border-t border-slate-100">
                          <span>Số mốc xác nhận: {activeVisitHandover.confirmations.length}</span>
                          <button
                            onClick={() => {
                              setActiveModalVisitId(null);
                              onNavigate('handovers', activeVisitHandover.id);
                            }}
                            className="font-bold text-indigo-600 hover:text-indigo-800 flex items-center"
                          >
                            <span>Xem tiến độ Bàn giao & Duyệt POD</span>
                            <ChevronRight className="w-3.5 h-3.5 ml-0.5" />
                          </button>
                        </div>
                      </div>
                    ) : (
                      <div className="text-slate-500 flex items-center justify-between">
                        <span>
                          {activeVisit.state === 'EXITED'
                            ? 'Container đã Exited, sẵn sàng tạo lệnh bàn giao cho đối tác vận chuyển.'
                            : 'Container chưa hoàn tất Gate-out. Có thể lập trước bản nháp DRAFT.'}
                        </span>
                        <button
                          onClick={() => {
                            setActiveModalVisitId(null);
                            onNavigate('handovers');
                          }}
                          className="px-3 py-1.5 bg-indigo-600 text-white rounded-lg font-bold hover:bg-indigo-700"
                        >
                          + Tạo Handover
                        </button>
                      </div>
                    )}
                  </div>

                  {/* Metadata Specs */}
                  <div className="grid grid-cols-2 gap-4">
                    <div className="border border-slate-200 rounded-xl p-3.5 space-y-2 bg-slate-50/50">
                      <div className="font-bold text-slate-800 border-b border-slate-200 pb-1">Hồ sơ hàng hóa</div>
                      <div>MBL: <strong className="font-mono">{activeVisit.mblNumber}</strong></div>
                      <div>HBL: <strong className="font-mono">{activeVisit.hblNumber}</strong></div>
                      <div>Seal Manifest: <strong className="font-mono">{activeVisit.manifestSeal}</strong></div>
                      <div>Seal Tiếp nhận: <strong className="font-mono text-blue-700">{activeVisit.actualSeal || '—'}</strong></div>
                      <div>Trọng lượng tổng: <strong>{activeVisit.grossWeightKg.toLocaleString()} kg</strong></div>
                    </div>

                    <div className="border border-slate-200 rounded-xl p-3.5 space-y-2 bg-slate-50/50">
                      <div className="font-bold text-slate-800 border-b border-slate-200 pb-1">Vị trí & Thời gian</div>
                      <div>Vị trí Bãi: <strong className="font-mono text-emerald-700">{activeVisit.currentLocation || 'Chưa xếp'}</strong></div>
                      <div>Ngày vào cổng: <strong>{activeVisit.gateInAt ? new Date(activeVisit.gateInAt).toLocaleString('vi-VN') : '—'}</strong></div>
                      <div>Ngày ra cổng: <strong>{activeVisit.gateOutAt ? new Date(activeVisit.gateOutAt).toLocaleString('vi-VN') : '—'}</strong></div>
                      <div>Ngưỡng cảnh báo lưu bãi: <strong>{activeVisit.freeDays === undefined ? 'Chưa có dữ liệu chính sách' : `${activeVisit.freeDays} ngày`}</strong></div>
                    </div>
                  </div>
                </div>
              )}

              {/* TAB 2: YARD OPS */}
              {activeDetailTab === 'YARD_OPS' && (
                <div className="space-y-4">
                  <div className="flex items-center justify-between bg-slate-50 p-3 rounded-lg border border-slate-200">
                    <div>
                      <div className="font-bold text-slate-800">Vị trí hiện tại trong bãi:</div>
                      <div className="text-base font-mono font-bold text-blue-700">{activeVisit.currentLocation || 'Chưa có vị trí'}</div>
                    </div>
                    <button
                      onClick={() => {
                        setActiveModalVisitId(null);
                        onNavigate('yard', activeVisit.id);
                      }}
                      className="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-bold"
                    >
                      Đổi vị trí / Điều chuyển
                    </button>
                  </div>
                  <p className="text-slate-500 italic text-center py-4">
                    Nhật ký di chuyển và kiểm tra bãi được cập nhật từ thiết bị di động của nhân viên bãi (Yard Staff).
                  </p>
                </div>
              )}

              {/* TAB 3: BILLING */}
              {activeDetailTab === 'BILLING' && (
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <h4 className="font-bold text-slate-800">Danh sách Hóa đơn & Đơn dịch vụ</h4>
                    <button
                      onClick={() => {
                        setActiveModalVisitId(null);
                        onNavigate('billing', activeVisit.id);
                      }}
                      className="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg font-bold"
                    >
                      + Tạo Đơn Dịch Vụ
                    </button>
                  </div>

                  {activeVisitInvoices.length === 0 ? (
                    <div className="p-8 text-center text-slate-400 bg-slate-50 rounded-xl">Chưa phát sinh hóa đơn nào</div>
                  ) : (
                    activeVisitInvoices.map((inv) => (
                      <div key={inv.id} className="border border-slate-200 rounded-xl p-4 bg-white shadow-xs space-y-2">
                        <div className="flex items-center justify-between">
                          <span className="font-mono font-bold text-blue-700">{inv.invoiceNo}</span>
                          <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                            inv.status === 'PAID' ? 'bg-emerald-100 text-emerald-800' : 'bg-amber-100 text-amber-800'
                          }`}>
                            {inv.status}
                          </span>
                        </div>
                        <div className="flex justify-between text-slate-600">
                          <span>Tổng tiền: <strong>{inv.totalAmountVnd.toLocaleString()}₫</strong></span>
                          <span>Đã thanh toán: <strong className="text-emerald-700">{inv.paidAmountVnd.toLocaleString()}₫</strong></span>
                        </div>
                      </div>
                    ))
                  )}
                </div>
              )}

              {/* TAB 4: GATE PASS */}
              {activeDetailTab === 'GATE_PASS' && (
                <div className="space-y-4">
                  {!passesReady ? <CriticalDataNotice kind="gatePasses" visitId={activeVisit.id} /> : activeVisitGatePass ? (
                    <div className="border border-indigo-200 bg-indigo-50/40 rounded-xl p-5 text-center space-y-3">
                      <div className="inline-block px-3 py-1 bg-emerald-100 text-emerald-800 font-bold rounded-full">
                        PHIẾU RA CỔNG ĐANG HIỆU LỰC (ACTIVE)
                      </div>
                      <div className="text-xl font-mono font-bold text-slate-900">{activeVisitGatePass.code}</div>
                      <div className="text-slate-600">
                        Xe lấy hàng: <strong>{activeVisitGatePass.vehiclePlate}</strong> · Người nhận: <strong>{activeVisitGatePass.receiverName}</strong> ({activeVisitGatePass.receiverIdNumber})
                      </div>
                      <div className="p-4 bg-white rounded-xl inline-block border border-slate-200 shadow-xs">
                        <QRCode value={activeVisitGatePass.qrToken} size={160} data-testid="container-gate-pass-qr" />
                        <div className="text-[10px] font-mono text-slate-400 mt-1">{activeVisitGatePass.qrToken}</div>
                      </div>
                      <div className="text-slate-500">
                        Hạn sử dụng: <strong>{new Date(activeVisitGatePass.expiresAt).toLocaleString('vi-VN')}</strong>
                      </div>
                    </div>
                  ) : (
                    <div className="p-6 border border-slate-200 rounded-xl bg-slate-50 space-y-4">
                      <h4 className="font-bold text-slate-800">Phát hành Phiếu ra cổng (Gate Pass)</h4>
                      {evaluation.status === "ready" ? (
                        <div className="space-y-3">
                          <p className="text-emerald-700 font-semibold">
                            ✓ Container đã vượt qua 100% điều kiện kiểm tra sẵn sàng ra cổng (Readiness Pass).
                          </p>
                          <div className="grid grid-cols-3 gap-2">
                            <div>
                              <label htmlFor="containers-gp-plate" className="block text-slate-600 mb-1">Biển số xe nhận</label>
                              <input id="containers-gp-plate"
                                type="text"
                                value={gpPlate}
                                onChange={(e) => setGpPlate(e.target.value)}
                                className="w-full px-2.5 py-1.5 border border-slate-300 rounded bg-white"
                              />
                            </div>
                            <div>
                              <label htmlFor="containers-gp-receiver" className="block text-slate-600 mb-1">Tên người nhận</label>
                              <input id="containers-gp-receiver"
                                type="text"
                                value={gpReceiver}
                                onChange={(e) => setGpReceiver(e.target.value)}
                                className="w-full px-2.5 py-1.5 border border-slate-300 rounded bg-white"
                              />
                            </div>
                            <div>
                              <label htmlFor="containers-gp-cccd" className="block text-slate-600 mb-1">Số CMND / CCCD</label>
                              <input id="containers-gp-cccd"
                                type="text"
                                value={gpCccd}
                                onChange={(e) => setGpCccd(e.target.value)}
                                className="w-full px-2.5 py-1.5 border border-slate-300 rounded bg-white"
                              />
                            </div>
                          </div>
                          <button
                            onClick={async () => {
                              await action.run(() => createGatePass({
                                visitId: activeVisit.id,
                                vehiclePlate: gpPlate,
                                receiverName: gpReceiver,
                                receiverIdNumber: gpCccd,
                              }));
                            }}
                            className="w-full py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-lg transition"
                          >
                            Xác nhận Tạo Phiếu Ra Cổng & Sinh mã QR
                          </button>
                        </div>
                      ) : (
                        <div className="p-3 bg-amber-50 border border-amber-200 text-amber-900 rounded-lg">
                          <ReadinessNotice evaluation={evaluation} />
                        </div>
                      )}
                    </div>
                  )}
                </div>
              )}

              {/* TAB 5: HOLDS */}
              {activeDetailTab === 'HOLDS' && (
                <div className="space-y-4">
                  <CommandNotice notice={action.notice} />
      <CriticalDataNotice kind="holds" visitId={activeVisit.id} />
                  <div className="flex items-center justify-between">
                    <h4 className="font-bold text-slate-800">Lệnh giữ nghiệp vụ (Operational Holds)</h4>
                    <button
                      onClick={() => setShowAddHold(true)}
                      className="px-3 py-1.5 bg-rose-600 hover:bg-rose-700 text-white rounded-lg font-bold flex items-center space-x-1"
                    >
                      <Plus className="w-3.5 h-3.5" />
                      <span>Đặt lệnh giữ (Hold)</span>
                    </button>
                  </div>

                  {showAddHold && (
                    <div className="p-4 border border-rose-200 bg-rose-50/40 rounded-xl space-y-3">
                      <div className="font-bold text-rose-900">Thiết lập Lệnh giữ mới</div>
                      <div className="grid grid-cols-2 gap-2">
                        <div>
                          <label htmlFor="containers-new-hold-type" className="block text-slate-600 mb-1">Loại lệnh giữ</label>
                          <select id="containers-new-hold-type"
                            value={newHoldType}
                            onChange={(e) => setNewHoldType(e.target.value as HoldType)}
                            className="w-full px-2.5 py-1.5 border border-slate-300 rounded bg-white"
                          >
                            <option value="CUSTOMS">Hải quan (Customs Hold)</option>
                            <option value="SHIPPING_LINE">Hãng tàu (Shipping Line Hold)</option>
                            <option value="DAMAGE">Hư hỏng vỏ (Damage Hold)</option>
                            <option value="SECURITY">An ninh (Security Hold)</option>
                            <option value="DOCUMENT">Chứng từ (Document Hold)</option>
                            <option value="OTHER">Khác (Other)</option>
                          </select>
                        </div>
                        <div>
                          <label htmlFor="containers-new-hold-reason" className="block text-slate-600 mb-1">Lý do chi tiết*</label>
                          <input id="containers-new-hold-reason"
                            type="text"
                            placeholder="Nhập lý do giữ..."
                            value={newHoldReason}
                            onChange={(e) => setNewHoldReason(e.target.value)}
                            className="w-full px-2.5 py-1.5 border border-slate-300 rounded bg-white"
                          />
                        </div>
                      </div>
                      <div className="flex justify-end space-x-2">
                        <button
                          type="button"
                          onClick={() => setShowAddHold(false)}
                          className="px-3 py-1 border border-slate-300 rounded text-slate-600"
                        >
                          Hủy
                        </button>
                        <button
                          type="button"
                          onClick={async () => {
                            if (!newHoldReason.trim()) return;
                            const result = await createOperationalHold(activeVisit.id, newHoldType, newHoldReason.trim());
                            alert(result.message);
                            if (!result.success) return;
                            setNewHoldReason('');
                            setShowAddHold(false);
                          }}
                          className="px-3 py-1 bg-rose-600 text-white rounded font-bold"
                        >
                          Lưu Lệnh Giữ
                        </button>
                      </div>
                    </div>
                  )}

                  <div className="space-y-2">
                    {activeVisitHolds.map((h) => (
                      <div
                        key={h.id}
                        className={`p-3 rounded-lg border flex items-center justify-between ${
                          h.status === 'ACTIVE' ? 'bg-rose-50/50 border-rose-200' : 'bg-slate-50 border-slate-200 text-slate-400'
                        }`}
                      >
                        <div>
                          <div className="flex items-center space-x-2">
                            <span className="font-bold text-slate-900">[{h.holdType}]</span>
                            <span className={`px-2 py-0.2 rounded-full text-[10px] font-bold ${
                              h.status === 'ACTIVE' ? 'bg-rose-100 text-rose-800' : 'bg-slate-200 text-slate-600'
                            }`}>
                              {h.status}
                            </span>
                          </div>
                          <div className="text-slate-700 mt-1">{h.reason}</div>
                          <div className="text-[11px] text-slate-400 mt-0.5">Đặt bởi: {h.placedBy}</div>
                        </div>

                        {h.status === 'ACTIVE' && (
                          <button
                            onClick={async () => {
                              const note = prompt('Nhập lý do giải phóng lệnh giữ:');
                              if (note) alert((await releaseOperationalHold(h.id, note)).message);
                            }}
                            className="px-3 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-lg"
                          >
                            Release Hold
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* TAB 6: TIMELINE */}
              {activeDetailTab === 'TIMELINE' && (
                <div className="space-y-4">
                  <h4 className="font-bold text-slate-800">Dòng thời gian sự kiện (Container Lifecycle Events)</h4>
                  <div className="pl-4 border-l-2 border-blue-400 space-y-4">
                    {activeVisit.gateOutAt && (
                      <div className="relative">
                        <div className="w-2.5 h-2.5 rounded-full bg-slate-900 absolute -left-[21px] top-1"></div>
                        <div className="font-bold text-slate-800">Xác nhận ra cổng (Gate-out)</div>
                        <div className="text-slate-500">{new Date(activeVisit.gateOutAt).toLocaleString('vi-VN')}</div>
                      </div>
                    )}
                    {activeVisit.currentLocation && (
                      <div className="relative">
                        <div className="w-2.5 h-2.5 rounded-full bg-blue-600 absolute -left-[21px] top-1"></div>
                        <div className="font-bold text-slate-800">Xếp vị trí bãi {activeVisit.currentLocation}</div>
                        <div className="text-slate-500">Đã lưu trữ an toàn trong khu vực bãi</div>
                      </div>
                    )}
                    {activeVisit.gateInAt && (
                      <div className="relative">
                        <div className="w-2.5 h-2.5 rounded-full bg-emerald-600 absolute -left-[21px] top-1"></div>
                        <div className="font-bold text-slate-800">Tiếp nhận vào cổng (Gate-in)</div>
                        <div className="text-slate-500">{new Date(activeVisit.gateInAt).toLocaleString('vi-VN')}</div>
                      </div>
                    )}
                    <div className="relative">
                      <div className="w-2.5 h-2.5 rounded-full bg-slate-400 absolute -left-[21px] top-1"></div>
                      <div className="font-bold text-slate-800">Khai báo Manifest</div>
                      <div className="text-slate-500">{activeVisit.manifestNo}</div>
                    </div>
                  </div>
                </div>
              )}
            </div>

            {/* Modal Footer */}
            <div className="pt-3 border-t border-slate-200 flex justify-end shrink-0">
              <button
                onClick={() => setActiveModalVisitId(null)}
                className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-lg text-xs"
              >
                Đóng
              </button>
            </div>
          </div>
        </ModalOverlay>
      )}

      {/* Create Container Visit Modal */}
      {showCreateVisit && (
        <ModalOverlay aria-labelledby="containers-dialog-2-title" onClose={() => setShowCreateVisit(false)} className="fixed inset-0 bg-slate-900/40 backdrop-blur-xs flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-lg w-full p-6 shadow-xl border border-slate-200 text-xs">
            <h3 id="containers-dialog-2-title" className="text-base font-bold text-slate-900 mb-4">Tạo Container Visit thủ công</h3>
            <div className="space-y-3">
              <div>
                <label htmlFor="containers-cv-form-container-number" className="block font-semibold text-slate-700 mb-1">Số container* (ISO 6346)</label>
                <input id="containers-cv-form-container-number"
                  type="text"
                  value={cvForm.containerNumber}
                  onChange={(e) => setCvForm({ ...cvForm, containerNumber: e.target.value.toUpperCase() })}
                  placeholder="Ví dụ: MSCU1234567"
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg uppercase font-mono"
                />
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label htmlFor="containers-cv-form-container-type" className="block font-semibold text-slate-700 mb-1">Loại container</label>
                  <select id="containers-cv-form-container-type"
                    value={cvForm.containerType}
                    onChange={(e) => setCvForm({ ...cvForm, containerType: e.target.value as ContainerVisit['containerType'] })}
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg bg-white"
                  >
                    <option value="20GP">20GP</option>
                    <option value="40GP">40GP</option>
                    <option value="40HC">40HC</option>
                    <option value="20RF">20RF</option>
                    <option value="45HC">45HC</option>
                  </select>
                </div>
                <div>
                  <label htmlFor="containers-create-shipping-line" className="block font-semibold text-slate-700 mb-1">Hãng tàu</label>
                  <input id="containers-create-shipping-line" readOnly value={formManifest?.shippingLine || ''} placeholder="Theo Manifest đã chọn" aria-label="Hãng tàu theo Manifest" className="w-full px-3 py-2 border border-slate-300 rounded-lg" />
                </div>
              </div>
              <div>
                <label htmlFor="containers-create-consignee" className="block font-semibold text-slate-700 mb-1">Chủ hàng (Consignee)*</label>
                <select id="containers-create-consignee" aria-label="Chủ hàng" value={cvForm.consigneeName} onChange={e => setCvForm({...cvForm,consigneeName:e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg"><option value="">Chọn chủ hàng</option>{consignees.filter(c => c.active).map(c => <option key={c.id} value={c.name}>{c.name}</option>)}</select>
              </div>
              <div className="grid grid-cols-3 gap-3">
                <div>
                  <label htmlFor="containers-create-manifest" className="block font-semibold text-slate-700 mb-1">Manifest No.</label>
                  <select id="containers-create-manifest" aria-label="Manifest" value={cvForm.manifestNo} onChange={e => setCvForm({...cvForm,manifestNo:e.target.value,mblNumber:'',hblNumber:''})} className="w-full px-3 py-2 border border-slate-300 rounded-lg"><option value="">Chọn Manifest</option>{manifests.filter(m => m.status !== 'CANCELLED').map(m => <option key={m.id} value={m.manifestNo}>{m.manifestNo}</option>)}</select>
                </div>
                <div>
                  <label htmlFor="containers-create-mbl" className="block font-semibold text-slate-700 mb-1">MBL No.</label>
                  <select id="containers-create-mbl" aria-label="Master BL" value={cvForm.mblNumber} onChange={e => setCvForm({...cvForm,mblNumber:e.target.value,hblNumber:''})} className="w-full px-3 py-2 border border-slate-300 rounded-lg"><option value="">Chọn MBL</option>{formManifest?.masterBills.map(m => <option key={m.id} value={m.mblNumber}>{m.mblNumber}</option>)}</select>
                </div>
                <div>
                  <label htmlFor="containers-create-hbl" className="block font-semibold text-slate-700 mb-1">HBL No.</label>
                  <select id="containers-create-hbl" aria-label="House BL" value={cvForm.hblNumber} onChange={e => {const h = formMaster?.houseBills.find(h => h.hblNumber === e.target.value);setCvForm({...cvForm,hblNumber:e.target.value,consigneeName:h?.consigneeName || cvForm.consigneeName});}} className="w-full px-3 py-2 border border-slate-300 rounded-lg"><option value="">Chọn HBL</option>{formMaster?.houseBills.map(h => <option key={h.id} value={h.hblNumber}>{h.hblNumber}</option>)}</select>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label htmlFor="containers-cv-form-manifest-seal" className="block font-semibold text-slate-700 mb-1">Seal Manifest*</label>
                  <input id="containers-cv-form-manifest-seal" type="text" value={cvForm.manifestSeal} onChange={(e) => setCvForm({ ...cvForm, manifestSeal: e.target.value })} className="w-full px-3 py-2 border border-slate-300 rounded-lg" />
                </div>
                <div>
                  <label htmlFor="containers-cv-form-gross-weight-kg" className="block font-semibold text-slate-700 mb-1">Trọng lượng (kg)</label>
                  <input id="containers-cv-form-gross-weight-kg" type="number" value={cvForm.grossWeightKg} onChange={(e) => setCvForm({ ...cvForm, grossWeightKg: Number(e.target.value) })} className="w-full px-3 py-2 border border-slate-300 rounded-lg" />
                </div>
              </div>
            </div>
            <div className="flex justify-end space-x-2 pt-4 mt-3 border-t border-slate-200">
              <button onClick={() => setShowCreateVisit(false)} className="px-4 py-2 border border-slate-300 text-slate-700 rounded-lg font-medium">Hủy</button>
              <button
                onClick={async () => {
                  const res = await createContainerVisit(cvForm);
                  alert(res.message);
                  if (res.success) {
                    setShowCreateVisit(false);
                    setCvForm({ containerNumber: '', containerType: '40HC', consigneeName: '', shippingLine: 'MSC', manifestNo: '', mblNumber: '', hblNumber: '', manifestSeal: '', grossWeightKg: 0 });
                  }
                }}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700"
              >
                Tạo Container Visit
              </button>
            </div>
          </div>
        </ModalOverlay>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { EdiOutboxMessage } from '../types';
import {
  FileCode2,
  Send,
  Download,
  Copy,
  CheckCircle2,
  Clock,
  Search,
  Check,
  RefreshCw,
} from 'lucide-react';

import { useCommandAction, CommandNotice } from './useCommandAction';
import { CollectionState } from './CollectionState';

export const EDIView: React.FC = () => {
  const { currentUser, ediMessages, retryEdiMessage, ediRoutes, ediAlerts, upsertEdiRoute, dispatchEdiOutbox, acknowledgeEdiAlert, resolveEdiAlert } = useApp();

  const can = (permission: string) => currentUser.permissionCodes?.some(code => code === '*' || code === permission) ?? false;
  const action = useCommandAction();
  const [tab, setTab] = useState<'OUTBOX' | 'ROUTES' | 'ALERTS'>('OUTBOX');
  const [selectedEdiId, setSelectedEdiId] = useState<string | null>(ediMessages[0]?.id || null);
  const selectedEdi = ediMessages.find((m) => m.id === selectedEdiId) || null;
  const [copied, setCopied] = useState(false);
  const [filterType, setFilterType] = useState<string>('ALL');

  const filteredEdi = ediMessages.filter((m) => {
    if (filterType !== 'ALL' && m.messageType !== filterType) return false;
    return true;
  });

  const handleCopy = async (payload: string) => {
    try {
      await navigator.clipboard.writeText(payload);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch { alert('Không thể sao chép nội dung.'); }
  };

  const handleResend = async (ediId: string) => {
    const result = await action.run(() => retryEdiMessage(ediId));
    if (result?.success) setSelectedEdiId(ediId);
  };

  return (
    <div className="space-y-6">
      <CommandNotice notice={action.notice} />
      {/* Header */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center space-x-2">
            <FileCode2 className="w-5 h-5 text-blue-600" />
            <span>Trung tâm Trao đổi Dữ liệu Điện tử (EDI Center)</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Giao tiếp tự động chuẩn UN/EDIFACT (CODECO_GATE_IN, CODECO_GATE_OUT, COREOR) với các Hãng tàu quốc tế và Cục Hải quan
          </p>
        </div>

        <div className="flex items-center space-x-2 text-xs">
          <div className="flex gap-1 bg-slate-100 p-1 rounded-lg mr-1">
            <button aria-pressed={tab === 'OUTBOX'} onClick={() => setTab('OUTBOX')} className={`px-3 py-1.5 rounded-md font-bold ${tab === 'OUTBOX' ? 'bg-white shadow-xs text-blue-700' : 'text-slate-500'}`}>Outbox</button>
            <button aria-pressed={tab === 'ROUTES'} onClick={() => setTab('ROUTES')} className={`px-3 py-1.5 rounded-md font-bold ${tab === 'ROUTES' ? 'bg-white shadow-xs text-blue-700' : 'text-slate-500'}`}>Routes</button>
            <button aria-pressed={tab === 'ALERTS'} onClick={() => setTab('ALERTS')} className={`px-3 py-1.5 rounded-md font-bold relative ${tab === 'ALERTS' ? 'bg-white shadow-xs text-blue-700' : 'text-slate-500'}`}>
              Alerts
              {ediAlerts.some((a) => a.status === 'OPEN') && <span className="absolute -top-1 -right-1 w-2 h-2 bg-rose-500 rounded-full"></span>}
            </button>
          </div>
          {tab === 'OUTBOX' && (
            <>
              <select
                value={filterType}
                onChange={(e) => setFilterType(e.target.value)}
                className="px-3 py-2 border border-slate-200 rounded-lg bg-slate-50 font-semibold text-slate-700"
              >
                <option value="ALL">Tất cả loại điện tín</option>
                <option value="CODECO_GATE_IN">CODECO Gate In</option>
                <option value="CODECO_GATE_OUT">CODECO Gate Out</option>
                <option value="COREOR">COREOR Release Order</option>
              </select>
              <button disabled={action.pending || !can("edi.dispatch")}
                onClick={async () => {
                  await action.run(dispatchEdiOutbox);
                }}
                className="px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-lg flex items-center gap-1.5"
              >
                <Send className="w-3.5 h-3.5" /> Chạy Dispatcher
              </button>
            </>
          )}
        </div>
      </div>

      {tab === 'ROUTES' && (
        <div className="bg-white rounded-xl border border-slate-200 shadow-xs overflow-hidden">
          <table className="w-full text-xs">
            <thead className="bg-slate-50 text-slate-500 uppercase text-[10px]">
              <tr>
                <th className="text-left px-4 py-3">Hãng tàu</th>
                <th className="text-left px-4 py-3">Transport</th>
                <th className="text-left px-4 py-3">Outbound Format</th>
                <th className="text-left px-4 py-3">Đích (Partner Target)</th>
                <th className="text-left px-4 py-3">Trạng thái</th>
                <th className="text-right px-4 py-3">Hành động</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100"><tr><td colSpan={6}><CollectionState resource="ediRoutes" count={ediRoutes.length} /></td></tr>
              {ediRoutes.map((r) => (
                <tr key={r.shippingLineId} className="hover:bg-slate-50">
                  <td className="px-4 py-3 font-bold text-slate-800">{r.shippingLineName}</td>
                  <td className="px-4 py-3">
                    <select
                      aria-label={`Transport ${r.shippingLineName}`} disabled={action.pending || !can("edi.manage")} value={r.transport}
                      onChange={(e) => { const transport = e.target.value; if (transport === "MOCK" || transport === "HTTPS" || transport === "SFTP") void action.run(() => upsertEdiRoute({ ...r, transport })); }}
                      className="px-2 py-1 border border-slate-300 rounded-md bg-white font-mono text-[11px]"
                    >
                      <option value="MOCK">MOCK</option>
                      <option value="HTTPS">HTTPS</option>
                      <option value="SFTP">SFTP</option>
                    </select>
                  </td>
                  <td className="px-4 py-3 font-mono text-slate-500 text-[11px]">{r.outboundFormat}</td>
                  <td className="px-4 py-3 font-mono text-slate-500 text-[11px]">{r.partnerTarget || '—'}</td>
                  <td className="px-4 py-3">
                    <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${r.enabled ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-200 text-slate-600'}`}>
                      {r.enabled ? 'ENABLED' : 'DISABLED'}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right">
                    <button
                      disabled={action.pending || !can("edi.manage")} onClick={() => void action.run(() => upsertEdiRoute({ ...r, enabled: !r.enabled }))}
                      className={`px-2.5 py-1 rounded-md font-bold text-[11px] border ${r.enabled ? 'bg-rose-50 text-rose-700 border-rose-200' : 'bg-emerald-50 text-emerald-700 border-emerald-200'}`}
                    >
                      {r.enabled ? 'Tắt' : 'Bật'}
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {tab === 'ALERTS' && (
        <div className="space-y-3">
          <CollectionState resource="ediAlerts" count={ediAlerts.length} />
          {ediAlerts.map((a) => (
            <div key={a.id} className="bg-white rounded-xl border border-slate-200 p-4 text-xs flex items-start justify-between gap-4">
              <div>
                <div className="flex items-center gap-2 mb-1">
                  <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                    a.status === 'OPEN' ? 'bg-rose-100 text-rose-800' : a.status === 'ACKNOWLEDGED' ? 'bg-amber-100 text-amber-800' : 'bg-emerald-100 text-emerald-800'
                  }`}>
                    {a.status}
                  </span>
                  <span className="font-mono font-bold text-slate-800">{a.containerNumber}</span>
                  <span className="text-slate-400">· {a.shippingLine}</span>
                </div>
                <p className="text-slate-600">{a.message}</p>
                <p className="text-slate-400 mt-1">{new Date(a.createdAt).toLocaleString('vi-VN')}</p>
                {a.resolutionNote && <p className="text-emerald-700 mt-1">✓ {a.resolutionNote}</p>}
              </div>
              {a.status !== 'RESOLVED' && (
                <div className="flex flex-col gap-1.5 shrink-0">
                  {a.status === 'OPEN' && (
                    <button disabled={action.pending || !can("edi.alert.manage")} onClick={() => void action.run(() => acknowledgeEdiAlert(a.id))} className="px-2.5 py-1 bg-amber-50 hover:bg-amber-100 text-amber-800 rounded-md font-bold border border-amber-200">
                      Đã xem
                    </button>
                  )}
                  <button
                    onClick={() => {
                      const note = window.prompt('Ghi chú xử lý:');
                      if (note) void action.run(() => resolveEdiAlert(a.id, note));
                    }}
                    className="px-2.5 py-1 bg-emerald-50 hover:bg-emerald-100 text-emerald-800 rounded-md font-bold border border-emerald-200"
                  >
                    Đánh dấu đã xử lý
                  </button>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {tab === 'OUTBOX' && (
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left Column: Messages List */}
        <div className="space-y-2">
          <CollectionState resource="ediMessages" count={filteredEdi.length} total={ediMessages.length} filtered={filterType !== "ALL"} onClear={() => setFilterType("ALL")} />
          {filteredEdi.map((edi) => {
            const isSelected = selectedEdi?.id === edi.id;
            return (
              <button type="button" aria-pressed={isSelected}
                key={edi.id}
                onClick={() => setSelectedEdiId(edi.id)}
                className={`block w-full text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-600 focus-visible:ring-offset-2 p-4 rounded-xl border cursor-pointer transition ${
                  isSelected
                    ? 'bg-blue-50/60 border-blue-500 shadow-xs'
                    : 'bg-white border-slate-200 hover:border-slate-300'
                }`}
              >
                <span className="block flex items-center justify-between">
                  <span className="font-mono font-bold text-xs text-blue-700">{edi.messageType}</span>
                  <span
                    className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                      edi.status === 'SENT'
                        ? 'bg-emerald-100 text-emerald-800'
                        : edi.status === 'PROCESSING'
                        ? 'bg-blue-100 text-blue-800'
                        : edi.status === 'FAILED'
                        ? 'bg-rose-100 text-rose-800'
                        : 'bg-amber-100 text-amber-800'
                    }`}
                  >
                    {edi.status}
                  </span>
                </span>
                <span className="block font-mono font-bold text-slate-800 text-xs mt-1">{edi.containerNumber}</span>
                <span className="block flex items-center justify-between text-[11px] text-slate-500 mt-2">
                  <span>Hãng tàu: <strong className="text-slate-700">{edi.shippingLine}</strong></span>
                  <span>{new Date(edi.createdAt).toLocaleTimeString('vi-VN')}</span>
                </span>
              </button>
            );
          })}
        </div>

        {/* Right 2 Columns: Payload & Transmission Inspector */}
        <div className="lg:col-span-2">
          {selectedEdi ? (
            <div className="bg-white rounded-xl border border-slate-200 shadow-xs p-6 space-y-5 text-xs">
              <div className="flex items-center justify-between border-b border-slate-200 pb-4">
                <div>
                  <div className="flex items-center space-x-2">
                    <span className="text-base font-bold text-slate-900 font-mono">Điện tín {selectedEdi.messageType}</span>
                    <span className="px-2 py-0.5 bg-blue-100 text-blue-800 font-bold rounded">
                      Hãng nhận: {selectedEdi.shippingLine}
                    </span>
                  </div>
                  <p className="text-slate-500 mt-0.5">
                    Container liên quan: <strong className="font-mono text-slate-800">{selectedEdi.containerNumber}</strong> · Idempotency Key: <span className="font-mono text-slate-600">{selectedEdi.idempotencyKey}</span>
                  </p>
                </div>

                <div className="flex items-center space-x-2">
                  <button
                    disabled={selectedEdi.payloadSnapshot == null} onClick={() => handleCopy(JSON.stringify(selectedEdi.payloadSnapshot, null, 2))}
                    className="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-lg flex items-center space-x-1"
                  >
                    {copied ? <Check className="w-3.5 h-3.5 text-emerald-600" /> : <Copy className="w-3.5 h-3.5" />}
                    <span>{copied ? 'Đã sao chép' : 'Copy'}</span>
                  </button>
                  {selectedEdi.status !== 'SENT' && can('edi.manage') && (
                    <button
                      disabled={action.pending} onClick={() => handleResend(selectedEdi.id)}
                      className="px-3 py-1.5 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-lg flex items-center space-x-1"
                    >
                      <RefreshCw className="w-3.5 h-3.5" />
                      <span>Gửi lại (Retry Transmission)</span>
                    </button>
                  )}
                </div>
              </div>

              {/* Status and Transmission metadata */}
              <div className="grid grid-cols-3 gap-3 p-3 bg-slate-50 rounded-xl border border-slate-200">
                <div>
                  <span className="text-slate-400">Trạng thái truyền:</span>
                  <div className="font-bold text-slate-800 mt-0.5">{selectedEdi.status}</div>
                </div>
                <div>
                  <span className="text-slate-400">Thời gian tạo:</span>
                  <div className="font-semibold text-slate-800 mt-0.5">
                    {new Date(selectedEdi.createdAt).toLocaleString('vi-VN')}
                  </div>
                </div>
                <div>
                  <span className="text-slate-400">Số lần thử lại:</span>
                  <div className="font-semibold text-slate-800 mt-0.5">
                    {selectedEdi.retryCount} lần
                  </div>
                </div>
              </div>

              {/* Raw EDI Payload Output */}
              <div>
                <div className="font-bold text-slate-700 uppercase tracking-wider text-[11px] mb-2">
                  Bản ghi payload từ backend (JSON):
                </div>
                <pre className="p-4 bg-slate-900 text-emerald-400 font-mono text-xs rounded-xl overflow-x-auto leading-relaxed border border-slate-800">
                  {selectedEdi.payloadSnapshot == null ? 'Backend chưa cung cấp bản ghi payload cho điện tín này.' : JSON.stringify(selectedEdi.payloadSnapshot, null, 2)}
                </pre>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-xl border border-slate-200 p-12 text-center text-slate-400 text-xs">
              Chọn một điện tín bên trái để xem nội dung mã hóa EDIFACT
            </div>
          )}
        </div>
      </div>
      )}
    </div>
  );
};

import { ModalOverlay } from './ModalOverlay';
import React, { useEffect, useState } from 'react';
import QRCode from 'react-qr-code';
import { useApp } from '../context/AppContext';
import { readinessLabel } from '../services/readiness-labels';
import { GatePass, ContainerVisit } from '../types';
import {
  QrCode,
  LogOut,
  CheckCircle2,
  AlertCircle,
  Clock,
  Send,
  Plus,
  Search,
  Scan,
  ShieldCheck,
  Truck,
  ExternalLink,
} from 'lucide-react';
import { NavTabId } from './Sidebar';
import { useBackendReadiness } from './useBackendReadiness';
import { CriticalDataNotice } from './CriticalDataNotice';

import { useCommandAction, CommandNotice } from './useCommandAction';
import { useFormValidation, FormErrors } from './useFormValidation';
import { CollectionState } from './CollectionState';
import { effectiveGatePassStatus, gatePassStatusMessage } from '../lib/gate-pass';
import { ReadinessNotice } from './ReadinessNotice';

interface GatePassViewProps {
  targetGatePassId?: string;
  onNavigate: (tab: NavTabId, contextId?: string) => void;
  targetVisitId?: string;
}

export const GatePassView: React.FC<GatePassViewProps> = ({ onNavigate, targetVisitId, targetGatePassId }) => {
  const {
    currentUser, gatePasses,
    containerVisits,
    scanAndGateOut,
    createGatePass,
    cancelGatePass,
  } = useApp();

  const can = (permission: string) => currentUser.permissionCodes?.some(code => code === '*' || code === permission) ?? false;
  const action = useCommandAction();
  const validation = useFormValidation();
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedGatePassId, setSelectedGatePassId] = useState<string | null>(targetGatePassId || gatePasses[0]?.id || null);
  const selectedGatePass = gatePasses.find((g) => g.id === selectedGatePassId) || null;
  const selectedStatus = selectedGatePass ? effectiveGatePassStatus(selectedGatePass) : null;
  const [showIssueModal, setShowIssueModal] = useState(false);

  // Tra cứu phiếu từ dữ liệu backend; xác nhận Gate-out là command riêng.
  const [scannerInput, setScannerInput] = useState('');
  const [scanResult, setScanResult] = useState<{ success: boolean; message: string } | null>(null);

  // Issue Form state
  const eligibleContainers = containerVisits.filter(
    (c) => ['IN_YARD', 'STRIPPED', 'UNDER_INSPECTION', 'IN_STRIPPING'].includes(c.state)
  );
  const [issueVisitId, setIssueVisitId] = useState(targetVisitId || '');
  const [vehiclePlate, setVehiclePlate] = useState('');
  const [receiverName, setReceiverName] = useState('');
  const [receiverCccd, setReceiverCccd] = useState('');
  const evaluation = useBackendReadiness(showIssueModal ? issueVisitId : null);
  const { readiness, isCheckingReadiness } = evaluation;

  useEffect(() => {
    if (targetVisitId && can("gate_pass.create")) { setIssueVisitId(targetVisitId); setShowIssueModal(true); }
  }, [targetVisitId]);
  useEffect(() => {
    if (!selectedGatePassId && gatePasses.length) setSelectedGatePassId(gatePasses[0].id);
  }, [gatePasses, selectedGatePassId]);

  useEffect(() => { if (targetGatePassId) setSelectedGatePassId(targetGatePassId); }, [targetGatePassId]);

  const filteredPasses = gatePasses.filter(
    (gp) =>
      gp.code.toLowerCase().includes(searchTerm.toLowerCase()) ||
      gp.containerNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
      gp.vehiclePlate.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleIssueGatePass = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!can("gate_pass.create") || action.isPending() || !validation.validate(e.currentTarget) || evaluation.status !== "ready") return;

    const res = await action.run(() => createGatePass({
      visitId: issueVisitId,
      vehiclePlate,
      receiverName,
      receiverIdNumber: receiverCccd,
    }));

    if (res?.success && res.gatePass) {
      setSelectedGatePassId(res.gatePass.id);
      setShowIssueModal(false);
    }
  };

  const handleFindPass = (e: React.FormEvent) => {
    e.preventDefault();
    if (!scannerInput.trim()) return;

    const target = gatePasses.find(
      (gp) =>
        gp.qrToken.toLowerCase() === scannerInput.trim().toLowerCase() ||
        gp.code.toLowerCase() === scannerInput.trim().toLowerCase()
    );

    if (!target) {
      setScanResult({
        success: false,
        message: 'Không tìm thấy Phiếu ra cổng nào khớp với mã quét!',
      });
      return;
    }

    setSelectedGatePassId(target.id);
    setScanResult({
      success: true,
      message: `Tìm thấy phiếu ${target.code} (${target.containerNumber}) · ${target.status}. Backend kiểm tra lại khi xác nhận ra cổng.`,
    });
  };

  const handleConfirmExit = async (pass: GatePass) => {
    if (!can("gate_pass.use") || effectiveGatePassStatus(pass) !== "ACTIVE") return;
    const res = await action.run(() => scanAndGateOut(pass.qrToken || pass.code));
    if (res?.success) {
      setSelectedGatePassId(pass.id);
    }
  };

  return (
    <div className="space-y-6">
      <CriticalDataNotice kind="gatePasses" />
      {/* Header */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center space-x-2">
            <QrCode className="w-5 h-5 text-indigo-600" />
            <span>Phiếu ra cổng (Gate Pass) & Kiểm soát Xuất kho</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Phát hành mã QR Code ra cổng có thời hạn 24 giờ, đối soát cổng Outbound và xác nhận Gate-out
          </p>
        </div>

        {can("gate_pass.create") && <button
          onClick={() => { action.clear(); setShowIssueModal(true); }}
          className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold text-xs rounded-lg transition shadow-xs flex items-center space-x-1.5"
        >
          <Plus className="w-4 h-4" />
          <span>Cấp Phiếu ra cổng mới</span>
        </button>}
      </div>

      {/* Tra cứu mã phiếu */}
      <div className="bg-slate-900 text-white p-4 rounded-xl shadow-xs flex flex-col md:flex-row md:items-center justify-between gap-3 text-xs">
        <div className="flex items-center space-x-3">
          <div className="w-8 h-8 rounded-lg bg-indigo-500 text-white flex items-center justify-center shrink-0">
            <Scan className="w-4 h-4" />
          </div>
          <div>
            <div className="font-bold text-slate-100">Tra cứu phiếu ra cổng</div>
            <div className="text-slate-400 text-[11px]">Quét mã QR từ app tài xế hoặc nhập mã GP-XXXX để xác thực</div>
          </div>
        </div>

        <form onSubmit={handleFindPass} className="flex items-center space-x-2">
          <input
            type="text"
            placeholder="Nhập mã QR Token hoặc GP Code..."
            value={scannerInput}
            onChange={(e) => setScannerInput(e.target.value)}
            className="px-3 py-1.5 bg-slate-800 border border-slate-700 rounded-lg text-white font-mono text-xs w-64 focus:outline-none focus:ring-1 focus:ring-indigo-400"
          />
          <button
            type="submit"
            className="px-3.5 py-1.5 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded-lg transition"
          >
            Quét mã
          </button>
        </form>
      </div>

      {scanResult && (
        <div
          className={`p-3 rounded-lg text-xs font-semibold flex items-center space-x-2 ${
            scanResult.success ? 'bg-emerald-50 text-emerald-800 border border-emerald-200' : 'bg-rose-50 text-rose-800 border border-rose-200'
          }`}
        >
          {scanResult.success ? <CheckCircle2 className="w-4 h-4" /> : <AlertCircle className="w-4 h-4" />}
          <span>{scanResult.message}</span>
        </div>
      )}

      {!showIssueModal && <CommandNotice notice={action.notice} />}
      {/* Main Grid: Gate Passes list & Pass QR Detail */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left: Passes List */}
        <div className="space-y-3">
          <div className="relative">
            <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
            <input
              type="text"
              placeholder="Tìm mã GP, số cont, biển số xe..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-3 py-2 text-xs bg-white border border-slate-200 rounded-lg focus:outline-none focus:ring-1 focus:ring-indigo-500"
            />
          </div>

          <div className="space-y-2">
<CollectionState resource="gatePasses" count={filteredPasses.length} total={gatePasses.length} filtered={!!searchTerm} onClear={() => setSearchTerm('')} />
            {filteredPasses.map((gp) => {
              const isSelected = selectedGatePass?.id === gp.id;
              const effectiveStatus = effectiveGatePassStatus(gp);
              return (
                <button type="button" aria-pressed={isSelected}
                  key={gp.id}
                  onClick={() => setSelectedGatePassId(gp.id)}
                  className={`block w-full text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-600 focus-visible:ring-offset-2 p-4 rounded-xl border cursor-pointer transition ${
                    isSelected
                      ? 'bg-indigo-50/60 border-indigo-500 shadow-xs'
                      : 'bg-white border-slate-200 hover:border-slate-300'
                  }`}
                >
                  <span className="block flex items-center justify-between">
                    <span className="text-xs font-mono font-bold text-indigo-700">{gp.code}</span>
                    <span
                      className={`px-2 py-0.5 text-[10px] font-bold rounded-full ${
                        effectiveStatus === 'ACTIVE'
                          ? 'bg-emerald-100 text-emerald-800'
                          : gp.status === 'USED'
                          ? 'bg-slate-200 text-slate-700'
                          : 'bg-rose-100 text-rose-800'
                      }`}
                    >
                      {effectiveStatus}
                    </span>
                  </span>
                  <span className="block font-mono font-bold text-slate-800 text-xs mt-1">{gp.containerNumber}</span>
                  <span className="block text-[11px] text-slate-500 mt-1 flex justify-between">
                    <span>Xe: {gp.vehiclePlate}</span>
                    <span>Tài xế: {gp.receiverName}</span>
                  </span>
                </button>
              );
            })}
          </div>
        </div>

        {/* Right 2 Columns: Gate Pass Inspection & Gate-out Execution */}
        <div className="lg:col-span-2">
          {selectedGatePass ? (
            <div className="bg-white rounded-xl border border-slate-200 shadow-xs p-6 space-y-6 text-xs">
              <div className="flex items-center justify-between border-b border-slate-200 pb-4">
                <div>
                  <div className="flex items-center space-x-2">
                    <h3 className="text-lg font-bold font-mono text-slate-900">{selectedGatePass.code}</h3>
                    <span
                      className={`px-2.5 py-0.5 rounded-full text-xs font-bold ${
                        selectedStatus === 'ACTIVE'
                          ? 'bg-emerald-100 text-emerald-800'
                          : selectedGatePass.status === 'USED'
                          ? 'bg-slate-200 text-slate-800'
                          : 'bg-rose-100 text-rose-800'
                      }`}
                    >
                      {selectedStatus}
                    </span>
                  </div>
                  <p className="text-slate-500 mt-0.5">
                    Phát hành lúc: {new Date(selectedGatePass.issuedAt).toLocaleString('vi-VN')}
                  </p>
                </div>

                <div className="text-right">
                  <span className="text-slate-400">Hiệu lực đến:</span>
                  <div className="font-bold text-slate-800">
                    {new Date(selectedGatePass.expiresAt).toLocaleString('vi-VN')}
                  </div>
                </div>
              </div>

              {/* QR Code Presentation Box */}
              <div className="bg-slate-50 border border-slate-200 rounded-2xl p-6 text-center space-y-3">
                <div className="bg-white p-4 rounded-xl border border-slate-200 inline-block shadow-xs">
                  {selectedStatus === 'ACTIVE' && selectedGatePass.qrToken ? <QRCode value={selectedGatePass.qrToken} size={160} data-testid="gate-pass-qr" /> : <p>QR chỉ hiển thị với phiếu còn hiệu lực và tài khoản có quyền phát hành.</p>}
                </div>
                <div className="font-mono text-slate-500 font-semibold break-all text-[10px] max-w-full">{selectedStatus === 'ACTIVE' ? selectedGatePass.qrToken : ''}</div>
                <div className="text-slate-600 max-w-sm mx-auto">
                  {selectedStatus && gatePassStatusMessage(selectedStatus)}
                </div>
              </div>

              {/* Vehicle & Receiver verification */}
              <div className="grid grid-cols-2 gap-4">
                <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200 space-y-1.5">
                  <div className="font-bold text-slate-800">Thông tin Phương tiện</div>
                  <div>Biển số đăng ký: <strong className="font-mono">{selectedGatePass.vehiclePlate}</strong></div>
                  <div>Người nhận hàng: <strong>{selectedGatePass.receiverName}</strong></div>
                  <div>Số CMND/CCCD: <strong className="font-mono">{selectedGatePass.receiverIdNumber}</strong></div>
                </div>

                <div className="p-3.5 bg-slate-50 rounded-xl border border-slate-200 space-y-1.5">
                  <div className="font-bold text-slate-800">Hồ sơ Container</div>
                  <div>Số container: <strong className="font-mono text-indigo-700">{selectedGatePass.containerNumber}</strong></div>
                  <div>Mã chuyến tiếp nhận: <strong className="font-mono text-slate-600">{selectedGatePass.containerVisitId}</strong></div>
                  <div className="text-slate-500">Điều kiện được backend kiểm tra lại khi xác nhận ra cổng.</div>
                </div>
              </div>

              {/* Gate-out Action */}
              <div className="pt-4 border-t border-slate-200 flex items-center justify-between">
                <div className="text-slate-500">
                  {selectedStatus && gatePassStatusMessage(selectedStatus)}
                </div>

                {selectedStatus === 'ACTIVE' ? (
                  <div className="flex items-center gap-2">
                    {can("gate_pass.create") && <button disabled={action.pending}
                      onClick={async () => {
                        const reason = window.prompt('Lý do hủy Gate Pass:');
                        if (reason && window.confirm(`Hủy phiếu ${selectedGatePass.code}?`)) await action.run(() => cancelGatePass(selectedGatePass.id, reason));
                      }}
                      className="px-4 py-2.5 bg-rose-50 hover:bg-rose-100 text-rose-700 font-bold rounded-lg border border-rose-200 transition"
                    >
                      Hủy Gate Pass
                    </button>}
                    {can("gate_pass.use") && <button disabled={action.pending}
                      onClick={() => handleConfirmExit(selectedGatePass)}
                      className="px-5 py-2.5 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded-lg shadow-sm flex items-center space-x-2 transition"
                    >
                      <LogOut className="w-4 h-4" />
                      <span>Xác nhận Ra cổng (Gate-out)</span>
                    </button>}
                  </div>
                ) : selectedStatus === "USED" && can("handover.read") ? (
                  <button
                    onClick={() => onNavigate('handovers')}
                    className="px-4 py-2 bg-indigo-600 hover:bg-indigo-700 text-white font-bold rounded-lg flex items-center space-x-1.5"
                  >
                    <Send className="w-3.5 h-3.5" />
                    <span>Tiến hành bàn giao vận chuyển</span>
                  </button>
                ) : null}
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-xl border border-slate-200 p-12 text-center text-slate-400 text-xs">
              Chọn một Phiếu ra cổng bên trái để xem chi tiết mã QR
            </div>
          )}
        </div>
      </div>

      {/* Issue Modal */}
      {showIssueModal && (
        <ModalOverlay aria-labelledby="gate-pass-dialog-1-title" pending={action.pending} onClose={() => { if (!action.isPending()) setShowIssueModal(false); }} className="fixed inset-0 bg-slate-900/40 backdrop-blur-xs flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-6 shadow-xl border border-slate-200 text-xs">
            <h3 id="gate-pass-dialog-1-title" className="text-base font-bold text-slate-900 mb-2">Phát hành Phiếu ra cổng (Gate Pass)</h3>
            <p className="text-slate-500 mb-4">
              Chọn container để kiểm tra hồ sơ, thanh toán và lệnh giữ từ backend trước khi phát hành.
            </p>

            <form noValidate onSubmit={handleIssueGatePass} className="space-y-4"><FormErrors errors={validation.errors} /><CommandNotice notice={action.notice} /><fieldset disabled={action.pending} className="space-y-4">
              <div>
                <label htmlFor="gate-pass-issue-visit-id" className="block font-semibold text-slate-700 mb-1">Chọn container trong bãi*</label>
                {eligibleContainers.length === 0 ? (
                  <div className="p-3 bg-amber-50 border border-amber-200 text-amber-900 rounded-lg">
                    Chưa có container trong bãi để kiểm tra.
                  </div>
                ) : (
                  <select required {...validation.props("gate-pass-issue-visit-id")} id="gate-pass-issue-visit-id"
                    value={issueVisitId}
                    onChange={(e) => setIssueVisitId(e.target.value)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg font-mono font-bold bg-white"
                  >
                    <option value="">Chọn container…</option>
                    {eligibleContainers.map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.containerNumber} — {c.consigneeName} ({c.currentLocation})
                      </option>
                    ))}
                  </select>
                )}
              </div>

              <ReadinessNotice evaluation={evaluation} />

              <div>
                <label htmlFor="gate-pass-receiver-vehicle-plate" className="block font-semibold text-slate-700 mb-1">Biển số xe nhận hàng*</label>
                <input
                  id="gate-pass-receiver-vehicle-plate" {...validation.props("gate-pass-receiver-vehicle-plate")}
                  type="text"
                  required
                  value={vehiclePlate}
                  aria-label="Biển số xe nhận hàng"
                  onChange={(e) => setVehiclePlate(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg uppercase font-mono"
                />
              </div>

              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label htmlFor="gate-pass-receiver-name" className="block font-semibold text-slate-700 mb-1">Tên tài xế / Người nhận*</label>
                  <input
                    id="gate-pass-receiver-name"
                    type="text"
                    required
                    value={receiverName}
                    aria-label="Tên tài xế / Người nhận"
                    onChange={(e) => setReceiverName(e.target.value)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg"
                  />
                </div>
                <div>
                  <label htmlFor="gate-pass-receiver-cccd" className="block font-semibold text-slate-700 mb-1">Số CMND / CCCD*</label>
                  <input
                    id="gate-pass-receiver-cccd"
                    type="text"
                    required
                    value={receiverCccd}
                    aria-label="Số CMND / CCCD"
                    onChange={(e) => setReceiverCccd(e.target.value)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg"
                  />
                </div>
              </div>

              </fieldset><div className="flex justify-end space-x-2 pt-3 border-t border-slate-200">
                <button
                  type="button" disabled={action.pending}
                  onClick={() => setShowIssueModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-slate-700"
                >
                  Hủy
                </button>
                <button
                  type="submit"
                  disabled={action.pending || !readiness || readiness.blockers.length > 0 || isCheckingReadiness}
                  className="px-4 py-2 bg-indigo-600 text-white rounded-lg font-bold hover:bg-indigo-700 disabled:opacity-50"
                >
                  Phát hành & Sinh mã QR
                </button>
              </div>
            </form>
          </div>
        </ModalOverlay>
      )}
    </div>
  );
};

import { ModalOverlay } from './ModalOverlay';
import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';
import {
  TransportHandover,
  HandoverStatus,
  PartnerApiClient,
  CustomerWarehouse,
  TransportConfirmation,
} from '../types';
import {
  Send,
  Plus,
  Search,
  CheckCircle2,
  Clock,
  Truck,
  Building2,
  Warehouse,
  FileCheck,
  ChevronRight,
  Code2,
  Play,
  ShieldCheck,
  Upload,
  AlertTriangle,
  ExternalLink,
} from 'lucide-react';
import { NavTabId } from './Sidebar';

interface HandoversViewProps {
  onNavigate: (tab: NavTabId, contextId?: string) => void;
  targetHandoverId?: string;
}

export const HandoversView: React.FC<HandoversViewProps> = ({ onNavigate, targetHandoverId }) => {
  const {
    handovers,
    partnerClients,
    warehouses,
    containerVisits,
    createHandover,
    publishHandover,
    icdConfirmHandover,
  } = useApp();

  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('ALL');
  const [selectedHandover, setSelectedHandover] = useState<TransportHandover | null>(
    (targetHandoverId ? handovers.find((h) => h.id === targetHandoverId) : null) || handovers[0] || null
  );

  useEffect(() => {
    setSelectedHandover(previous => handovers.find(h => h.id === (targetHandoverId ?? previous?.id)) ?? handovers[0] ?? null);
  }, [handovers, targetHandoverId]);

  const [showCreateModal, setShowCreateModal] = useState(false);

  // New Handover form
  const [selectedContVisitId, setSelectedContVisitId] = useState(
    containerVisits.find((c) => c.state === 'EXITED')?.id || containerVisits[0]?.id || ''
  );
  const [selectedPartnerClientId, setSelectedPartnerClientId] = useState(partnerClients[0]?.id || '');
  const [selectedWarehouseId, setSelectedWarehouseId] = useState(warehouses[0]?.id || '');
  const [transportCodeInput, setTransportCodeInput] = useState('');

  const filteredHandovers = handovers.filter((h) => {
    if (searchTerm) {
      const q = searchTerm.toLowerCase();
      const matchCode = h.transportCode.toLowerCase().includes(q);
      const matchCont = h.containerNumber.toLowerCase().includes(q);
      const matchPartner = h.partnerName.toLowerCase().includes(q);
      if (!matchCode && !matchCont && !matchPartner) return false;
    }
    if (statusFilter !== 'ALL' && h.status !== statusFilter) return false;
    return true;
  });

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    const cont = containerVisits.find((c) => c.id === selectedContVisitId);
    const client = partnerClients.find((p) => p.id === selectedPartnerClientId);
    const wh = warehouses.find((w) => w.id === selectedWarehouseId);
    if (!cont || !client || !wh) return;

    const res = await createHandover({
