            </div></form>
          </div>
        </ModalOverlay>
      )}

    </div>
  );
};

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { Route, CheckCircle2, XCircle, Clock, Search } from 'lucide-react';
import { NavTabId } from './Sidebar';

import { vietnamDateTimeInput, vietnamDateTimeToIso } from '../lib/time';
import { useCommandAction, CommandNotice } from './useCommandAction';

interface MovementOrdersViewProps {
  onNavigate?: (tab: NavTabId, contextId?: string) => void;
  targetVisitId?: string;
}

export const MovementOrdersView: React.FC<MovementOrdersViewProps> = ({ onNavigate, targetVisitId }) => {
  const { movementOrders, containerVisits, createMovementOrder, authorizeMovementOrder, cancelMovementOrder } = useApp();
  const action = useCommandAction();
  const [searchTerm, setSearchTerm] = useState('');
  const [expiresAt, setExpiresAt] = useState(vietnamDateTimeInput(Date.now() + 86400000));

  const statusBadge = (status: string) => {
    const map: Record<string, string> = {
      DRAFT: 'bg-amber-100 text-amber-800',
      AUTHORIZED: 'bg-emerald-100 text-emerald-800',
      EXPIRED: 'bg-slate-200 text-slate-600',
      CANCELLED: 'bg-rose-100 text-rose-800',
    };
    return <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${map[status] || 'bg-slate-100 text-slate-600'}`}>{status}</span>;
  };

  const eligibleVisits = containerVisits.filter(
    (v) => v.state === 'PENDING' && !movementOrders.some((o) => o.containerVisitId === v.id && o.status !== 'CANCELLED')
  );

  const filtered = movementOrders.filter(
    (o) =>
      o.orderCode.toLowerCase().includes(searchTerm.toLowerCase()) ||
      o.containerNumber.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="space-y-5">
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center space-x-2">
            <Route className="w-5 h-5 text-blue-600" />
            <span>Movement Order — Lệnh cho phép container di chuyển về ICD</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Mắt xích bắt buộc giữa Container Visit (PENDING) và Truck Visit/Gate-in. Chỉ khi Authorize thành công, container mới đủ điều kiện vào cổng.
          </p>
        </div>
        <div className="relative w-64">
          <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
          <input
            type="text"
            placeholder="Tìm mã lệnh, số container..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-9 pr-3 py-2 text-xs bg-white border border-slate-200 rounded-lg focus:outline-none focus:ring-1 focus:ring-blue-500"
          />
        </div>
      </div>

      <CommandNotice notice={action.notice} />
      <label className="block text-sm text-slate-700">Thời hạn khi duyệt lệnh (giờ Việt Nam UTC+7)
        <input aria-label="Thời hạn khi duyệt lệnh (giờ Việt Nam UTC+7)" type="datetime-local" value={expiresAt} onChange={e => setExpiresAt(e.target.value)} className="ml-3 rounded-lg border border-slate-300 px-3 py-2" />
      </label>
      {eligibleVisits.length > 0 && (
        <div className="bg-amber-50 border border-amber-200 rounded-xl p-4">
          <h4 className="text-xs font-bold text-amber-900 mb-2">
            {eligibleVisits.length} Container Visit đang PENDING chưa có Movement Order:
          </h4>
          <div className="flex flex-wrap gap-2">
            {eligibleVisits.map((v) => (
              <button
                key={v.id}
                disabled={action.pending} onClick={async () => {
                  await action.run(() => createMovementOrder(v.id));
                }}
                className="px-3 py-1.5 bg-white hover:bg-amber-100 border border-amber-300 rounded-lg text-xs font-bold text-amber-900"
              >
                + Tạo lệnh cho {v.containerNumber}
              </button>
            ))}
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl border border-slate-200 shadow-xs overflow-hidden">
        <table className="w-full text-xs">
          <thead className="bg-slate-50 text-slate-500 uppercase text-[10px]">
            <tr>
              <th className="text-left px-4 py-3">Mã lệnh</th>
              <th className="text-left px-4 py-3">Container</th>
              <th className="text-left px-4 py-3">Trạng thái</th>
              <th className="text-left px-4 py-3">Tạo lúc</th>
              <th className="text-left px-4 py-3">Hết hạn</th>
              <th className="text-left px-4 py-3">Duyệt bởi</th>
              <th className="text-right px-4 py-3">Hành động</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filtered.map((o) => (
              <tr key={o.id} className="hover:bg-slate-50">
                <td className="px-4 py-3 font-mono font-bold text-slate-800">{o.orderCode}</td>
                <td className="px-4 py-3 font-mono">{o.containerNumber}</td>
                <td className="px-4 py-3">{statusBadge(o.status)}</td>
                <td className="px-4 py-3 text-slate-500">{new Date(o.createdAt).toLocaleString('vi-VN')}</td>
                <td className="px-4 py-3 text-slate-500">{o.expiresAt ? new Date(o.expiresAt).toLocaleString('vi-VN') : '—'}</td>
                <td className="px-4 py-3 text-slate-500">{o.authorizedBy || '—'}</td>
                <td className="px-4 py-3 text-right space-x-2">
                  {o.status === 'DRAFT' && (
                    <>
                      <button
                        disabled={action.pending} onClick={async () => { const instant = vietnamDateTimeToIso(expiresAt); if (!instant || new Date(instant).getTime() <= Date.now()) { alert('Chọn thời hạn trong tương lai.'); return; } await action.run(() => authorizeMovementOrder(o.id, instant)); }}
                        className="px-2.5 py-1 bg-emerald-600 hover:bg-emerald-700 text-white rounded-md font-bold inline-flex items-center gap-1"
                      >
                        <CheckCircle2 className="w-3 h-3" /> Authorize
                      </button>
                      <button
                        onClick={async () => {
                          const reason = window.prompt('Lý do hủy:');
                          if (reason && window.confirm(`Hủy lệnh ${o.orderCode}?`)) await action.run(() => cancelMovementOrder(o.id, reason));
                        }}
                        className="px-2.5 py-1 bg-rose-50 hover:bg-rose-100 text-rose-700 rounded-md font-bold border border-rose-200 inline-flex items-center gap-1"
                      >
                        <XCircle className="w-3 h-3" /> Hủy
                      </button>
                    </>
                  )}
                  {o.status === 'AUTHORIZED' && onNavigate && (
                    <button
                      onClick={() => onNavigate('truck-visits', o.containerVisitId)}
                      className="px-2.5 py-1 bg-blue-50 hover:bg-blue-100 text-blue-700 rounded-md font-bold border border-blue-200 inline-flex items-center gap-1"
                    >
                      <Clock className="w-3 h-3" /> Tạo Truck Visit
                    </button>
                  )}
                </td>
              </tr>
            ))}
            {filtered.length === 0 && (
              <tr>
                <td colSpan={7} className="px-4 py-10 text-center text-slate-400">
                  Chưa có Movement Order nào phù hợp.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import { ModalOverlay } from './ModalOverlay';
import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { PartnerApiClient, PartnerApiLog } from '../types';
import { formatRedactedLogBody } from '../services/redacted-log-body';
import {
  KeyRound,
  FileCode,
  CheckCircle2,
  AlertCircle,
  Clock,
  Send,
  Plus,
  Copy,
  Check,
  RotateCw,
  Terminal,
} from 'lucide-react';

interface PartnerManagementViewProps {
  mode: 'CLIENTS' | 'LOGS';
}

export const PartnerManagementView: React.FC<PartnerManagementViewProps> = ({ mode }) => {
  const { partnerClients, partnerApiLogs, rotatePartnerApiKey, createPartnerClient } = useApp();
  const [copiedKey, setCopiedKey] = useState<string | null>(null);
  const [selectedLog, setSelectedLog] = useState<PartnerApiLog | null>(partnerApiLogs[0] || null);

  // New partner state
  const [showAddModal, setShowAddModal] = useState(false);
  const [newCode, setNewCode] = useState('');
  const [newName, setNewName] = useState('');
  const [newApiKeyResult, setNewApiKeyResult] = useState<string | null>(null);

  const handleCopy = async (text: string) => {
    try {
      await navigator.clipboard.writeText(text);
      setCopiedKey(text);
      setTimeout(() => setCopiedKey(null), 2000);
    } catch { alert('Không thể sao chép. Vui lòng chọn và sao chép khóa thủ công.'); }
  };

  const handleRotateKey = async (client: PartnerApiClient) => {
    const res = await rotatePartnerApiKey(client.id);
    if (!res.success || !res.plainApiKey) { alert(res.message); return; }
    alert(`Đã thu hồi API key cũ và cấp API key mới cho ${client.partnerName}:\n\n${res.plainApiKey}\n\n(Lưu ý: Khóa chỉ hiển thị một lần duy nhất)`);
  };

  const handleCreatePartner = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCode || !newName) return;
    const res = await createPartnerClient(newCode.trim().toUpperCase(), newName.trim(), ['read:handovers', 'write:confirmations']);
    if (res.success && res.plainApiKey) setNewApiKeyResult(res.plainApiKey);
    else alert(res.message);
  };

  if (mode === 'CLIENTS') {
    return (
      <div className="space-y-6">
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h2 className="text-lg font-bold text-slate-900 flex items-center space-x-2">
              <KeyRound className="w-5 h-5 text-indigo-600" />
              <span>Đối tác Tích hợp API Vận chuyển (Mô đun 13)</span>
            </h2>
            <p className="text-xs text-slate-500 mt-1">
              Quản lý API Key, phân quyền phạm vi (Scopes), cơ chế xoay vòng khóa bí mật (Rotation) và mã băm SHA-256 an toàn
            </p>
          </div>

          <button
            onClick={() => {
              setNewApiKeyResult(null);
              setNewCode('');
              setNewName('');
              setShowAddModal(true);
            }}
            className="px-3.5 py-2 bg-indigo-600 hover:bg-indigo-700 text-white text-xs font-bold rounded-lg shadow-xs flex items-center space-x-1.5 transition"
          >
            <Plus className="w-4 h-4" />
            <span>Thêm Đối tác API mới</span>
          </button>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-xs">
          {partnerClients.map((client) => (
            <div
              key={client.id}
              className="bg-white rounded-xl border border-slate-200 p-5 shadow-xs space-y-4 hover:border-indigo-300 transition"
            >
              <div className="flex items-center justify-between">
                <div>
                  <div className="text-sm font-bold text-slate-900">{client.partnerName}</div>
                  <span className="font-mono text-indigo-700 font-semibold">{client.partnerCode}</span>
                </div>
                <span
                  className={`px-2.5 py-0.5 rounded-full font-bold text-[10px] ${
                    client.status === 'ACTIVE' ? 'bg-emerald-100 text-emerald-800' : 'bg-rose-100 text-rose-800'
                  }`}
                >
                  {client.status}
                </span>
              </div>

              <div className="space-y-2 bg-slate-50 p-3 rounded-lg border border-slate-200">
                <div className="flex items-center justify-between">
                  <span className="text-slate-400 font-semibold">Masked API Key:</span>
                  <span className="font-mono text-slate-700 font-bold">
                    icd_live_••••••••••••{client.keyLast4}
                  </span>
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-slate-400 font-semibold">Băm SHA-256:</span>
                  <span className="font-mono text-slate-500 max-w-[180px] truncate" title={client.apiKeyHash}>
                    {client.apiKeyHash}
                  </span>
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-slate-400 font-semibold">Quyền (Scopes):</span>
                  <div className="flex flex-wrap gap-1">
                    {client.scopes.map((s) => (
                      <span key={s} className="px-1.5 py-0.5 bg-indigo-50 text-indigo-700 rounded text-[10px] font-mono">
                        {s}
                      </span>
                    ))}
                  </div>
                </div>

                <div className="flex items-center justify-between">
                  <span className="text-slate-400 font-semibold">Yêu cầu gần nhất:</span>
                  <span className="text-slate-700 font-medium">
                    {client.lastRequestAt ? new Date(client.lastRequestAt).toLocaleString('vi-VN') : 'Chưa có cuộc gọi nào'}
                  </span>
                </div>
              </div>

              <div className="flex justify-end pt-1">
                <button
                  onClick={() => handleRotateKey(client)}
                  className="px-3.5 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold rounded-lg flex items-center space-x-1.5 transition"
                >
                  <RotateCw className="w-3.5 h-3.5 text-indigo-600" />
                  <span>Xoay vòng Khóa (Rotate Key)</span>
                </button>
              </div>
            </div>
          ))}
        </div>

        {showAddModal && (
          <ModalOverlay aria-labelledby="partner-management-dialog-1-title" onClose={() => setShowAddModal(false)} className="fixed inset-0 bg-slate-900/40 backdrop-blur-xs flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl max-w-md w-full p-6 shadow-xl border border-slate-200 text-xs">
              <h3 id="partner-management-dialog-1-title" className="text-base font-bold text-slate-900 mb-2">Đăng ký Đối tác Tích hợp API mới</h3>

              {newApiKeyResult ? (
                <div className="space-y-4">
                  <div className="p-3 bg-emerald-50 border border-emerald-200 rounded-lg text-emerald-800">
                    Đối tác đã được tạo thành công! Hãy copy API Key dưới đây và cung cấp an toàn cho đối tác:
                  </div>
                  <div className="p-3 bg-slate-900 text-emerald-400 font-mono text-xs rounded-lg break-all">
                    {newApiKeyResult}
                  </div>
                  <div className="flex justify-end">
                    <button
                      onClick={() => setShowAddModal(false)}
                      className="px-4 py-2 bg-indigo-600 text-white font-bold rounded-lg hover:bg-indigo-700"
                    >
                      Hoàn tất
                    </button>
                  </div>
                </div>
              ) : (
                <form onSubmit={handleCreatePartner} className="space-y-4">
                  <div>
                    <label htmlFor="partner-management-new-code" className="block font-semibold text-slate-700 mb-1">Mã đối tác (Partner Code)*</label>
                    <input id="partner-management-new-code"
                      type="text"
                      required
                      placeholder="VD: TRANS_EXPRESS"
                      value={newCode}
                      onChange={(e) => setNewCode(e.target.value)}
                      className="w-full px-3 py-2 border border-slate-300 rounded-lg uppercase font-mono"
                    />
                  </div>

                  <div>
                    <label htmlFor="partner-management-new-name" className="block font-semibold text-slate-700 mb-1">Tên công ty đối tác*</label>
                    <input id="partner-management-new-name"
                      type="text"
                      required
                      placeholder="VD: Công ty TNHH Vận tải Toàn Cầu"
                      value={newName}
                      onChange={(e) => setNewName(e.target.value)}
                      className="w-full px-3 py-2 border border-slate-300 rounded-lg"
                    />
                  </div>

                  <div className="flex justify-end space-x-2 pt-3 border-t border-slate-200">
                    <button
                      type="button"
                      onClick={() => setShowAddModal(false)}
                      className="px-4 py-2 border border-slate-300 rounded-lg text-slate-700"
                    >
                      Hủy
                    </button>
                    <button
                      type="submit"
                      className="px-4 py-2 bg-indigo-600 text-white font-bold rounded-lg hover:bg-indigo-700"
                    >
                      Tạo & Cấp API Key
                    </button>
                  </div>
                </form>
              )}
            </div>
          </ModalOverlay>
        )}
      </div>
    );
  }

  // mode === 'LOGS'
  return (
    <div className="space-y-6">
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center space-x-2">
            <FileCode className="w-5 h-5 text-indigo-600" />
            <span>Nhật ký API Đối tác (Partner Integration Logs)</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Giám sát thời gian thực các cuộc gọi API từ đối tác: Accept chuyến, Xác nhận giao kho, Upload POD, Tọa độ GPS
          </p>
        </div>
        <span className="text-xs text-slate-500 bg-slate-100 px-3 py-1 rounded-lg font-semibold">
          {partnerApiLogs.length} cuộc gọi API đã ghi nhận
        </span>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Left: Logs list */}
        <div className="space-y-2">
          {partnerApiLogs.map((log) => {
            const isSelected = selectedLog?.id === log.id;
            return (
              <button type="button" aria-pressed={isSelected}
                key={log.id}
                onClick={() => setSelectedLog(log)}
                className={`block w-full text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-600 focus-visible:ring-offset-2 p-3.5 rounded-xl border cursor-pointer transition text-xs ${
                  isSelected
                    ? 'bg-indigo-50/70 border-indigo-500 shadow-xs'
                    : 'bg-white border-slate-200 hover:border-slate-300'
                }`}
              >
                <span className="block flex items-center justify-between">
                  <span className="px-2 py-0.5 bg-indigo-100 text-indigo-800 font-mono font-bold rounded text-[10px]">
                    {log.method}
                  </span>
                  <span
                    className={`font-mono font-bold ${
                      log.httpStatus === 200 ? 'text-emerald-600' : 'text-rose-600'
                    }`}
                  >
                    HTTP {log.httpStatus}
                  </span>
                </span>
                <span className="block font-mono text-slate-800 font-semibold mt-1 truncate">{log.endpoint}</span>
                <span className="block flex items-center justify-between text-[11px] text-slate-400 mt-1.5">
                  <span>Đối tác: <strong className="text-slate-700">{log.partnerName}</strong></span>
                  <span>{new Date(log.createdAt).toLocaleTimeString('vi-VN')}</span>
                </span>
              </button>
            );
          })}
        </div>

        {/* Right 2 Columns: Payload inspector */}
        <div className="lg:col-span-2">
          {selectedLog ? (
            <div className="bg-white rounded-xl border border-slate-200 shadow-xs p-5 space-y-4 text-xs">
              <div className="flex items-center justify-between border-b border-slate-200 pb-3">
                <div className="flex items-center space-x-2">
                  <span className="px-2 py-0.5 bg-indigo-600 text-white font-mono font-bold rounded">
                    {selectedLog.method}
                  </span>
                  <span className="font-mono font-bold text-slate-900 text-sm">{selectedLog.endpoint}</span>
                </div>
                <span className="text-slate-400 font-mono">Độ trễ: {selectedLog.latencyMs}ms</span>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <div className="font-bold text-slate-700 uppercase tracking-wider text-[10px] mb-1">
                    Request Body (Đã che giấu thông tin nhạy cảm)
                  </div>
                  <pre className="p-3 bg-slate-900 text-emerald-400 font-mono text-[11px] rounded-lg overflow-x-auto max-h-64 whitespace-pre-wrap">
                    {formatRedactedLogBody(selectedLog.requestBodyRedacted)}
                  </pre>
                </div>

                <div>
                  <div className="font-bold text-slate-700 uppercase tracking-wider text-[10px] mb-1">
                    Response Body
                  </div>
                  <pre className="p-3 bg-slate-900 text-blue-300 font-mono text-[11px] rounded-lg overflow-x-auto max-h-64 whitespace-pre-wrap">
                    {formatRedactedLogBody(selectedLog.responseBodyRedacted)}
                  </pre>
                </div>
              </div>
            </div>
          ) : (
            <div className="bg-white rounded-xl border border-slate-200 p-12 text-center text-slate-400 text-xs">
              Chọn một bản ghi API bên trái để kiểm tra gói tin
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { useApp } from '../context/AppContext';
import { getReportMetrics } from '../services/report-metrics';
import { BarChart3, TrendingUp, Ship, Clock, DollarSign, PieChart, Layers } from 'lucide-react';

export const ReportsView: React.FC = () => {
  const { containerVisits, invoices, yardSlots, handovers } = useApp();

  const {totalTeu,lineStats,dwellBuckets} = getReportMetrics(containerVisits);

  // Financial
  const totalRevenue = invoices.reduce((acc, i) => acc + i.totalAmountVnd, 0);
  const totalPaid = invoices.reduce((acc, i) => acc + i.paidAmountVnd, 0);

  // Yard occupancy
  const occupiedSlots = yardSlots.filter((s) => s.occupiedByContainerId).length;
  const occupancyRate = yardSlots.length > 0 ? ((occupiedSlots / yardSlots.length) * 100).toFixed(1) : '0';

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center space-x-2">
            <BarChart3 className="w-5 h-5 text-blue-600" />
            <span>Báo cáo Quản trị & Phân tích Hoạt động ICD (Analytics & Reports)</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Tổng hợp hồ sơ container hiện có, công suất bãi, thời gian lưu bãi và số tiền đã thu
          </p>
        </div>
      </div>

      {/* KPI Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-4 gap-4 text-xs">
        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs">
          <span className="text-slate-500 font-semibold uppercase tracking-wider">Tổng sản lượng TEU</span>
          <div className="text-2xl font-bold text-slate-900 mt-1">{totalTeu} TEU</div>
          <div className="text-slate-400 mt-1">Tính trên các hồ sơ container hiện có</div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs">
          <span className="text-slate-500 font-semibold uppercase tracking-wider">Tỷ lệ lấp đầy bãi</span>
          <div className="text-2xl font-bold text-blue-600 mt-1">{occupancyRate}%</div>
          <div className="text-slate-400 mt-1">{occupiedSlots} / {yardSlots.length} vị trí đang sử dụng</div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs">
          <span className="text-slate-500 font-semibold uppercase tracking-wider">Doanh thu thu về</span>
          <div className="text-2xl font-bold text-emerald-600 mt-1">{(totalPaid / 1000000).toFixed(1)}M ₫</div>
          <div className="text-slate-400 mt-1">Tổng xuất HĐ: {(totalRevenue / 1000000).toFixed(1)}M ₫</div>
        </div>

        <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs">
          <span className="text-slate-500 font-semibold uppercase tracking-wider">Chuyến bàn giao ngoại ICD</span>
          <div className="text-2xl font-bold text-indigo-600 mt-1">{handovers.length} chuyến</div>
          <div className="text-slate-400 mt-1">Số hồ sơ bàn giao đã lưu</div>
        </div>
      </div>

      {/* Breakdown: By Shipping Line */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs space-y-4">
          <h3 className="text-sm font-bold text-slate-900 flex items-center space-x-2">
            <Ship className="w-4 h-4 text-blue-600" />
            <span>Phân bổ Sản lượng TEU theo Hãng tàu</span>
          </h3>

          <div className="space-y-3 text-xs">
            {Object.entries(lineStats).map(([line, teu]) => {
              const percent = totalTeu > 0 ? ((teu / totalTeu) * 100).toFixed(0) : '0';
              return (
                <div key={line} className="space-y-1">
                  <div className="flex justify-between font-semibold text-slate-700">
                    <span>{line}</span>
                    <span>{teu} TEU ({percent}%)</span>
                  </div>
                  <div className="w-full bg-slate-100 rounded-full h-2 overflow-hidden">
                    <div className="bg-blue-600 h-2 rounded-full" style={{ width: `${percent}%` }}></div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>

        <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs space-y-4">
          <h3 className="text-sm font-bold text-slate-900 flex items-center space-x-2">
            <Layers className="w-4 h-4 text-indigo-600" />
            <span>Tình trạng Container Trong Bãi (Yard Dwell Time)</span>
          </h3>

          <div className="space-y-3 text-xs">
            {dwellBuckets.map(bucket => <div key={bucket.label} className="p-3 bg-slate-50 text-slate-800 rounded-lg flex flex-wrap gap-2 items-center justify-between font-semibold"><span>{bucket.label}</span><span>{bucket.count} container · {bucket.percent}%</span></div>)}
            <p className="text-slate-500">Tính từ ngày vào cổng của container còn trong ICD. Phí thực tế xem tại Dịch vụ & Thanh toán.</p>
          </div>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { canAccessWebTab } from '../services/permissions';
import { useApp } from '../context/AppContext';
import {
  LayoutDashboard,
  ListTodo,
  FileText,
  Boxes,
  Truck,
  LogIn,
  Warehouse,
  Receipt,
  QrCode,
  Radio,
  TruckIcon,
  KeyRound,
  FileCode,
  Settings,
  History,
  ChevronRight,
  ExternalLink,
  Route,
  Database,
  Users,
} from 'lucide-react';

export type NavTabId =
  | 'dashboard'
  | 'work-queue'
  | 'manifests'
  | 'containers'
  | 'movement-orders'
  | 'truck-visits'
  | 'gate-in'
  | 'yard'
  | 'billing'
  | 'gate-pass'
  | 'edi'
  | 'handovers'
  | 'partner-clients'
  | 'partner-api-logs'
  | 'master-data'
  | 'users-roles'
  | 'admin'
  | 'activity';

interface SidebarProps {
  activeTab: NavTabId;
  setActiveTab: (tab: NavTabId) => void;
  isOpen?: boolean;
}

export const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, isOpen = false }) => {
  const { currentUser, workQueue, handovers } = useApp();

  const workQueueCount = workQueue.length;
  const pendingHandoverReviewCount = handovers.filter((h) => h.status === 'PARTNER_CONFIRMED').length;

  const navItems = [
    {
      group: 'Tổng quan & Điều phối',
      items: [
        { id: 'dashboard', label: 'Tổng quan vận hành', icon: LayoutDashboard },
        {
          id: 'work-queue',
          label: 'Danh sách công việc',
          icon: ListTodo,
          badge: workQueueCount > 0 ? workQueueCount : undefined,
          badgeColor: 'bg-rose-500 text-white',
        },
      ],
    },
    {
      group: 'Quản lý Hàng hóa & Cổng',
      items: [
        { id: 'manifests', label: 'Bản lược khai (Manifest)', icon: FileText },
        { id: 'containers', label: 'Quản lý Container', icon: Boxes },
        { id: 'movement-orders', label: 'Movement Order', icon: Route },
        { id: 'truck-visits', label: 'Chuyến xe ra/vào', icon: Truck },
        { id: 'gate-in', label: 'Tiếp nhận vào cổng (Gate-in)', icon: LogIn },
        { id: 'yard', label: 'Vận hành Bãi (Yard)', icon: Warehouse },
      ],
    },
    {
      group: 'Tài chính & Ra cổng',
      items: [
        { id: 'billing', label: 'Dịch vụ & Thanh toán', icon: Receipt },
        { id: 'gate-pass', label: 'Phiếu ra cổng & Gate-out', icon: QrCode },
        { id: 'edi', label: 'Vận hành EDI (CODECO)', icon: Radio },
      ],
    },
    {
      group: 'Tích hợp đối tác',
      items: [
        {
          id: 'handovers',
          label: 'Bàn giao vận chuyển',
          icon: TruckIcon,
          badge: pendingHandoverReviewCount > 0 ? `${pendingHandoverReviewCount} chờ duyệt` : undefined,
          badgeColor: 'bg-amber-500 text-white',
        },
        { id: 'partner-clients', label: 'Đối tác tích hợp API', icon: KeyRound },
        { id: 'partner-api-logs', label: 'Nhật ký API đối tác', icon: FileCode },
      ],
    },
    {
      group: 'Hệ thống & Quản trị',
      items: [
        { id: 'master-data', label: 'Danh mục dùng chung', icon: Database },
        { id: 'users-roles', label: 'Người dùng & Phân quyền', icon: Users },
        { id: 'admin', label: 'Báo cáo vận hành', icon: Settings },
        { id: 'activity', label: 'Nhật ký kiểm toán', icon: History },
      ],
    },
  ];

  return (
    <aside aria-label="Điều hướng nghiệp vụ" className={`${isOpen ? 'flex' : 'hidden'} fixed left-0 top-16 bottom-0 z-40 w-64 bg-slate-900 text-slate-300 flex-col border-r border-slate-800 shrink-0 select-none md:static md:flex`}>
      <div className="flex-1 overflow-y-auto py-4 px-3 space-y-6 text-xs">
        {navItems.map(group => ({...group,items:group.items.filter(item => canAccessWebTab(currentUser,item.id))})).filter(group => group.items.length).map((group, idx) => (
          <div key={idx} className="space-y-1">
            <div className="px-3 text-caption font-bold uppercase tracking-wider text-slate-400">
              {group.group}
            </div>
            {group.items.map((item) => {
              const Icon = item.icon;
              const isActive = activeTab === item.id;
              return (
                <button
                  key={item.id}
                  onClick={() => setActiveTab(item.id as NavTabId)}
                  aria-current={isActive ? 'page' : undefined}
                  className={`w-full flex items-center justify-between px-3 py-2 rounded-lg font-medium transition-colors ${
                    isActive
                      ? 'bg-blue-600 text-white shadow-xs'
                      : 'text-slate-300 hover:bg-slate-800 hover:text-white'
                  }`}
                >
                  <div className="flex items-center space-x-2.5 truncate">
                    <Icon className={`w-4 h-4 shrink-0 ${isActive ? 'text-white' : 'text-slate-400'}`} />
                    <span className="truncate">{item.label}</span>
                  </div>
                  {item.badge && (
                    <span className={`px-1.5 py-0.5 text-caption font-bold rounded-full ${item.badgeColor}`}>
                      {item.badge}
                    </span>
                  )}
                </button>
              );
            })}
          </div>
        ))}
      </div>

      <div className="p-3 border-t border-slate-800 bg-slate-950/60 text-caption text-slate-400 space-y-1">
        <div className="font-semibold text-slate-200 truncate">{currentUser.name}</div>
        <div className="truncate">{currentUser.email}</div>
        <div className="text-blue-300">{currentUser.role}</div>
      </div>
    </aside>
  );
};

import { ModalOverlay } from './ModalOverlay';
import React, { useEffect, useState } from 'react';
import { useApp } from '../context/AppContext';
import { TruckVisit, TruckVisitStatus } from '../types';
import {
  Truck,
  Plus,
  Search,
  CheckCircle2,
  Clock,
  LogIn,
  LogOut,
  MapPin,
  Calendar,
} from 'lucide-react';
import { NavTabId } from './Sidebar';

import { useCommandAction, CommandNotice } from './useCommandAction';
import { useFormValidation, FormErrors } from './useFormValidation';
import { CollectionState } from './CollectionState';

interface TruckVisitsViewProps {
  targetVisitId?: string;
  onNavigate: (tab: NavTabId, contextId?: string) => void;
}

export const TruckVisitsView: React.FC<TruckVisitsViewProps> = ({ onNavigate, targetVisitId }) => {
  const { currentUser, truckVisits, createTruckVisit, updateTruckVisitStatus, containerVisits } = useApp();

  const can = (permission: string) => currentUser.permissionCodes?.some(code => code === '*' || code === permission) ?? false;
  const action = useCommandAction();
  const validation = useFormValidation();
  const [searchTerm, setSearchTerm] = useState('');
  const [showCreateModal, setShowCreateModal] = useState(false);

  // New Truck Visit form
  const [plate, setPlate] = useState('');
  const [driver, setDriver] = useState('');
  const [phone, setPhone] = useState('');
  const [transporter, setTransporter] = useState('');
  const [type, setType] = useState<'GATE_IN' | 'GATE_OUT'>('GATE_IN');
  const [selectedConts, setSelectedConts] = useState<string>('');

  useEffect(() => {
    if (!targetVisitId || !can('truck_visit.create')) return;
    const visit = containerVisits.find(v => v.id === targetVisitId);
    if (visit) { setSelectedConts(visit.containerNumber); setType('GATE_IN'); setShowCreateModal(true); }
  }, [targetVisitId, containerVisits]);

  const filteredVisits = truckVisits.filter(
    (tv) =>
      tv.vehiclePlate.toLowerCase().includes(searchTerm.toLowerCase()) ||
      tv.driverName.toLowerCase().includes(searchTerm.toLowerCase()) ||
      tv.visitCode.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleCreate = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!can("truck_visit.create") || action.isPending() || !validation.validate(e.currentTarget)) return;
    const result = await action.run(() => createTruckVisit({
      vehiclePlate: plate,
      driverName: driver,
      driverPhone: phone,
      transporterName: transporter,
      visitType: type,
      containerNumbers: [selectedConts],
      gateLane: undefined,
    }));
    if (result?.success) setShowCreateModal(false);
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center space-x-2">
            <Truck className="w-5 h-5 text-blue-600" />
            <span>Quản lý Chuyến xe ra/vào (Truck Visits)</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Đặt lịch hẹn trước tại cổng (Gate Appointment) nhằm rút ngắn thời gian xếp dỡ và tránh ùn tắc luồng xe
          </p>
        </div>

        {can("truck_visit.create") && <button
          onClick={() => { action.clear(); setShowCreateModal(true); }}
          className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white font-bold text-xs rounded-lg transition shadow-xs flex items-center space-x-1.5"
        >
          <Plus className="w-4 h-4" />
          <span>Tạo Chuyến xe mới</span>
        </button>}
      </div>

      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs flex items-center justify-between gap-4 text-xs">
        <div className="relative w-72">
          <Search className="w-4 h-4 text-slate-400 absolute left-3 top-2.5" />
          <input
            type="text"
            placeholder="Tìm biển số xe, tên tài xế, mã chuyến..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full pl-9 pr-3 py-2 border border-slate-200 rounded-lg bg-slate-50 focus:outline-none focus:ring-1 focus:ring-blue-500"
          />
        </div>
        <span className="text-slate-400">Hiển thị {filteredVisits.length} chuyến xe</span>
      </div>

      {!showCreateModal && <CommandNotice notice={action.notice} />}
      <CollectionState resource="truckVisits" count={filteredVisits.length} total={truckVisits.length} filtered={!!searchTerm} onClear={() => setSearchTerm('')} />
      {/* Visits List */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {filteredVisits.map((tv) => (
          <div key={tv.id} className="bg-white rounded-xl border border-slate-200 p-5 shadow-xs hover:border-blue-300 transition space-y-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                <span className={`p-1.5 rounded-lg ${tv.visitType === 'GATE_IN' ? 'bg-emerald-100 text-emerald-800' : 'bg-blue-100 text-blue-800'}`}>
                  {tv.visitType === 'GATE_IN' ? <LogIn className="w-4 h-4" /> : <LogOut className="w-4 h-4" />}
                </span>
                <span className="font-mono font-bold text-sm text-slate-900">{tv.visitCode}</span>
              </div>
              <span className={`px-2.5 py-0.5 rounded-full text-xs font-bold ${
                tv.status === 'ARRIVED' ? 'bg-amber-100 text-amber-800 border border-amber-300' :
                tv.status === 'COMPLETED' ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-100 text-slate-700'
              }`}>
                {tv.status}
              </span>
            </div>

            <div className="grid grid-cols-2 gap-3 text-xs text-slate-600">
              <div>
                <span className="text-slate-400">Biển số xe:</span>{' '}
                <strong className="text-slate-800 font-mono text-sm">{tv.vehiclePlate}</strong>
              </div>
              <div>
                <span className="text-slate-400">Tài xế:</span>{' '}
                <strong className="text-slate-800">{tv.driverName}</strong> ({tv.driverPhone})
              </div>
              <div>
                <span className="text-slate-400">Đơn vị vận tải:</span>{' '}
                <strong className="text-slate-700">{tv.transporterName}</strong>
              </div>
              <div>
                <span className="text-slate-400">Làn cổng:</span>{' '}
                <strong className="text-blue-700">{tv.gateLane || 'Chưa ghi nhận làn'}</strong>
              </div>
            </div>

            <div className="p-3 bg-slate-50 rounded-lg border border-slate-100 flex items-center justify-between text-xs">
              <div>
                <span className="text-slate-500">Container mang theo:</span>{' '}
                <span className="font-mono font-bold text-blue-700">{tv.containerNumbers.join(', ')}</span>
              </div>
              {tv.status === 'SCHEDULED' && can('truck_visit.arrive') && (
                <button
                  disabled={action.pending} onClick={() => void action.run(() => updateTruckVisitStatus(tv.id, 'ARRIVED'))}
                  className="px-3 py-1 bg-amber-600 hover:bg-amber-700 text-white font-bold rounded shadow-xs"
                >
                  Xác nhận xe đến cổng (ARRIVED)
                </button>
              )}
              {tv.status === 'ARRIVED' && tv.visitType === 'GATE_IN' && (
                <button
                  onClick={() => { const linkedVisit = containerVisits.find(v => tv.containerNumbers.includes(v.containerNumber)); if (linkedVisit) onNavigate('gate-in', linkedVisit.id); }}
                  className="px-3 py-1 bg-emerald-600 hover:bg-emerald-700 text-white font-bold rounded shadow-xs"
                >
                  Tiến hành Tiếp nhận (Gate-in) →
                </button>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Create Modal */}
      {showCreateModal && (
        <ModalOverlay aria-labelledby="truck-visits-dialog-1-title" pending={action.pending} onClose={() => { if (!action.isPending()) setShowCreateModal(false); }} className="fixed inset-0 bg-slate-900/40 backdrop-blur-xs flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl max-w-md w-full p-6 shadow-xl border border-slate-200 text-xs">
            <h3 id="truck-visits-dialog-1-title" className="text-base font-bold text-slate-900 mb-4">Tạo Lịch hẹn Chuyến xe (Truck Visit)</h3>
            <form noValidate onSubmit={handleCreate} className="space-y-3"><FormErrors errors={validation.errors} /><CommandNotice notice={action.notice} /><fieldset disabled={action.pending} className="space-y-3">
              <div>
                <label className="block font-semibold text-slate-700 mb-1">Loại chuyến xe</label>
                <div className="grid grid-cols-2 gap-2">
                  <button
                    type="button"
                    aria-pressed={type === 'GATE_IN'} onClick={() => setType('GATE_IN')}
                    className={`py-2 rounded-lg font-bold border transition ${
                      type === 'GATE_IN' ? 'bg-emerald-50 border-emerald-600 text-emerald-800' : 'border-slate-200 text-slate-600'
                    }`}
                  >
                    Vào cổng (Gate-in)
                  </button>
                  <button
                    type="button"
                    aria-pressed={type === 'GATE_OUT'} onClick={() => setType('GATE_OUT')}
                    className={`py-2 rounded-lg font-bold border transition ${
                      type === 'GATE_OUT' ? 'bg-blue-50 border-blue-600 text-blue-800' : 'border-slate-200 text-slate-600'
                    }`}
                  >
                    Ra cổng (Gate-out)
                  </button>
                </div>
              </div>

              <div>
                <label htmlFor="truck-visits-plate" className="block font-semibold text-slate-700 mb-1">Biển số đầu kéo*</label>
                <input {...validation.props("truck-visits-plate")} id="truck-visits-plate"
                  type="text"
                  required
                  value={plate}
                  onChange={(e) => setPlate(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg uppercase"
                />
              </div>

              <div className="grid grid-cols-2 gap-2">
                <div>
                  <label htmlFor="truck-visits-driver" className="block font-semibold text-slate-700 mb-1">Tên tài xế*</label>
                  <input {...validation.props("truck-visits-driver")} id="truck-visits-driver"
                    type="text"
                    required
                    value={driver}
                    onChange={(e) => setDriver(e.target.value)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg"
                  />
                </div>
                <div>
                  <label htmlFor="truck-visits-phone" className="block font-semibold text-slate-700 mb-1">Số điện thoại*</label>
                  <input {...validation.props("truck-visits-phone")} id="truck-visits-phone"
                    type="text"
                    required
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg"
                  />
                </div>
              </div>

              <div>
                <label htmlFor="truck-visits-transporter" className="block font-semibold text-slate-700 mb-1">Hãng vận tải (Transporter)</label>
                <input {...validation.props("truck-visits-transporter")} id="truck-visits-transporter"
                  type="text"
                  value={transporter}
                  onChange={(e) => setTransporter(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg"
                />
              </div>

              <div>
                <label htmlFor="truck-visits-selected-conts" className="block font-semibold text-slate-700 mb-1">Số Container gắn chuyến*</label>
                <input {...validation.props("truck-visits-selected-conts")} id="truck-visits-selected-conts"
                  type="text"
                  required
                  value={selectedConts}
                  onChange={(e) => setSelectedConts(e.target.value)}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg font-mono uppercase"
                />
              </div>

              </fieldset><div className="flex justify-end space-x-2 pt-3 border-t border-slate-200">
                <button
                  type="button"
                  disabled={action.pending} onClick={() => setShowCreateModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-slate-600"
                >
                  Hủy
                </button>
                <button
                  type="submit" disabled={action.pending}
                  className="px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700"
                >
                  {action.pending ? 'Đang lưu…' : 'Lưu Chuyến Xe'}
                </button>
              </div>
            </form>
          </div>
        </ModalOverlay>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { WorkQueueTask, TaskUrgency, TaskType } from '../types';
import {
  ListTodo,
  AlertOctagon,
  Clock,
  ArrowRight,
  Filter,
  CheckCircle2,
  LogIn,
  Warehouse,
  Receipt,
  QrCode,
  TruckIcon,
  RefreshCw,
} from 'lucide-react';
import { NavTabId } from './Sidebar';

interface WorkQueueViewProps {
  onNavigate: (tab: NavTabId, contextId?: string) => void;
  onOpenGateIn?: (visitId: string) => void;
  onOpenYardAssign?: (visitId: string) => void;
  onOpenBilling?: (visitId: string) => void;
  onOpenGateOut?: (containerNumber: string) => void;
  onOpenHandover?: (visitId: string) => void;
}

export const WorkQueueView: React.FC<WorkQueueViewProps> = ({
  onNavigate,
  onOpenGateIn,
  onOpenYardAssign,
  onOpenBilling,
  onOpenGateOut,
  onOpenHandover,
}) => {
  const { workQueue, currentUser } = useApp();

  const [urgencyFilter, setUrgencyFilter] = useState<string>('ALL');
  const [taskTypeFilter, setTaskTypeFilter] = useState<string>('ALL');
  const [filterMyRoleOnly, setFilterMyRoleOnly] = useState<boolean>(false);

  const filteredTasks = workQueue.filter((task) => {
    if (urgencyFilter !== 'ALL' && task.urgency !== urgencyFilter) return false;
    if (taskTypeFilter !== 'ALL' && task.taskType !== taskTypeFilter) return false;
    if (filterMyRoleOnly && !task.assignedRoles.includes(currentUser.role)) return false;
    return true;
  });

  const getUrgencyBadge = (urgency: TaskUrgency) => {
    switch (urgency) {
      case 'OVERDUE':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-bold bg-rose-100 text-rose-800 border border-rose-300">QUÁ HẠN</span>;
      case 'HIGH':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-bold bg-amber-100 text-amber-800 border border-amber-300">ƯU TIÊN CAO</span>;
      case 'MEDIUM':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-bold bg-yellow-100 text-yellow-800 border border-yellow-300">TRUNG BÌNH</span>;
      case 'NORMAL':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-bold bg-emerald-100 text-emerald-800 border border-emerald-300">BÌNH THƯỜNG</span>;
    }
  };

  const handleAction = (task: WorkQueueTask) => {
    switch (task.taskType) {
      case 'GATE_IN':
        if (onOpenGateIn) onOpenGateIn(task.containerVisitId);
        else onNavigate('gate-in', task.containerVisitId);
        break;
      case 'YARD_ASSIGN':
        if (onOpenYardAssign) onOpenYardAssign(task.containerVisitId);
        else onNavigate('yard', task.containerVisitId);
        break;
      case 'BILLING':
        if (onOpenBilling) onOpenBilling(task.containerVisitId);
        else onNavigate('billing', task.containerVisitId);
        break;
      case 'GATE_OUT':
        if (onOpenGateOut) onOpenGateOut(task.containerNumber);
        else onNavigate('gate-pass');
        break;
      case 'HANDOVER_REVIEW':
        if (onOpenHandover) onOpenHandover(task.containerVisitId);
        else onNavigate('handovers', task.containerVisitId);
        break;
      default:
        onNavigate('containers', task.containerVisitId);
    }
  };

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-xs flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-lg font-bold text-slate-900 flex items-center space-x-2">
            <ListTodo className="w-5 h-5 text-blue-600" />
            <span>Danh sách công việc thông minh (Work Queue)</span>
          </h2>
          <p className="text-xs text-slate-500 mt-1">
            Tự động sắp xếp các tác vụ theo mức độ khẩn cấp (Urgency) và cam kết thời gian hoàn thành (SLA)
          </p>
        </div>

        {/* Quick Urgency counters */}
        <div className="flex items-center space-x-2">
          <div className="px-3 py-1 bg-rose-50 border border-rose-200 rounded-lg text-xs">
            <span className="text-rose-600 font-bold">{workQueue.filter((t) => t.urgency === 'OVERDUE').length}</span> Overdue
          </div>
          <div className="px-3 py-1 bg-amber-50 border border-amber-200 rounded-lg text-xs">
            <span className="text-amber-600 font-bold">{workQueue.filter((t) => t.urgency === 'HIGH').length}</span> High
          </div>
          <div className="px-3 py-1 bg-blue-50 border border-blue-200 rounded-lg text-xs">
            <span className="text-blue-600 font-bold">{workQueue.length}</span> Tổng việc
          </div>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-xs flex flex-wrap items-center justify-between gap-3 text-xs">
        <div className="flex flex-wrap items-center gap-2">
          <span className="font-semibold text-slate-600 flex items-center">
            <Filter className="w-3.5 h-3.5 mr-1" /> Bộ lọc:
          </span>

          <select
            value={urgencyFilter}
            onChange={(e) => setUrgencyFilter(e.target.value)}
            className="border border-slate-200 rounded-lg px-2.5 py-1.5 bg-slate-50 text-slate-700 font-medium"
          >
            <option value="ALL">Tất cả mức độ khẩn cấp</option>
            <option value="OVERDUE">Quá hạn (OVERDUE)</option>
            <option value="HIGH">Ưu tiên cao (HIGH)</option>
            <option value="MEDIUM">Trung bình (MEDIUM)</option>
            <option value="NORMAL">Bình thường (NORMAL)</option>
          </select>

          <select
            value={taskTypeFilter}
            onChange={(e) => setTaskTypeFilter(e.target.value)}
            className="border border-slate-200 rounded-lg px-2.5 py-1.5 bg-slate-50 text-slate-700 font-medium"
          >
            <option value="ALL">Tất cả loại nghiệp vụ</option>
            <option value="GATE_IN">Tiếp nhận vào cổng (Gate-in)</option>
            <option value="YARD_ASSIGN">Xếp vị trí bãi (Yard Assign)</option>
            <option value="BILLING">Thu phí dịch vụ (Billing)</option>
            <option value="GATE_OUT">Xác nhận ra cổng (Gate-out)</option>
            <option value="HANDOVER_REVIEW">Duyệt bàn giao đối tác (Review POD)</option>
          </select>

          <label className="flex items-center space-x-1.5 cursor-pointer ml-2 text-slate-700 select-none">
            <input
              type="checkbox"
              checked={filterMyRoleOnly}
              onChange={(e) => setFilterMyRoleOnly(e.target.checked)}
              className="rounded border-slate-300 text-blue-600 focus:ring-blue-500"
            />
            <span>Chỉ việc thuộc vai trò của tôi ({currentUser.role})</span>
          </label>
        </div>

        <span className="text-slate-400">
          Hiển thị {filteredTasks.length} / {workQueue.length} tác vụ
        </span>
      </div>

      {/* Task List */}
      <div className="space-y-3">
        {filteredTasks.length === 0 ? (
          <div className="bg-white p-12 text-center rounded-xl border border-slate-200 shadow-xs">
            <CheckCircle2 className="w-12 h-12 text-emerald-500 mx-auto mb-3" />
            <h3 className="text-base font-bold text-slate-800">Không có công việc nào cần xử lý</h3>
            <p className="text-xs text-slate-500 mt-1">
              Toàn bộ các tác vụ theo tiêu chí lọc hiện tại đã được giải quyết hoặc chưa phát sinh.
            </p>
          </div>
        ) : (
          filteredTasks.map((task) => (
            <div
              key={task.id}
              className={`bg-white p-4 rounded-xl border transition shadow-xs flex flex-col md:flex-row md:items-center justify-between gap-4 ${
                task.urgency === 'OVERDUE'
                  ? 'border-rose-300 bg-rose-50/20'
                  : task.urgency === 'HIGH'
                  ? 'border-amber-300 bg-amber-50/10'
                  : 'border-slate-200 hover:border-blue-300'
              }`}
            >
              <div className="flex items-start space-x-3.5">
                <div className="pt-0.5">{getUrgencyBadge(task.urgency)}</div>
                <div>
                  <div className="flex items-center space-x-2">
                    <span className="text-sm font-bold text-slate-900">{task.title}</span>
                    <span className="text-xs font-mono font-bold px-2 py-0.5 bg-slate-100 text-slate-700 rounded-md">
                      {task.containerNumber}
                    </span>
                  </div>
                  <p className="text-xs text-slate-600 mt-1">{task.subtitle}</p>
                  <div className="flex items-center space-x-4 mt-2 text-caption text-slate-400">
                    <span className="flex items-center text-slate-500">
                      <Clock className="w-3.5 h-3.5 mr-1 text-slate-400" />
                      Thời hạn: <strong className="ml-1 text-slate-700">{task.timeRemainingText}</strong>
                    </span>
                    <span>
                      Vai trò xử lý: <strong className="text-slate-600">{task.assignedRoles.join(', ')}</strong>
                    </span>
                  </div>
                </div>
              </div>

              <div className="shrink-0 flex items-center space-x-2">
                <button
                  onClick={() => handleAction(task)}
                  className={`px-4 py-2 text-xs font-bold rounded-lg transition shadow-xs flex items-center space-x-1.5 ${
                    task.urgency === 'OVERDUE'
                      ? 'bg-rose-600 hover:bg-rose-700 text-white'
                      : 'bg-blue-600 hover:bg-blue-700 text-white'
                  }`}
                >
                  <span>Thực hiện tác vụ</span>
                  <ArrowRight className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};
